window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[31]={"id":"031","numero":31,"titre":"Accouchement normal","objectifs":[{"id":"31-1","rang":"A","rubrique":"Définition","titre":"Connaître les différents éléments du bassin maternel","contenu":"<div class=\"notion-course\"><p>Le <span>bassin maternel</span> est la structure osseuse qui constitue la <strong>filière pelvienne obstétricale</strong>. Sa connaissance anatomique conditionne la compréhension de l’engagement, de la descente et du dégagement du mobile fœtal.</p>\n\n      <h4>Ceinture pelvienne — anneau ostéo-articulaire</h4>\n\n      <ul>\n        <li><strong>4 os :</strong> <span class=\"nc-blue_bg\">2 os coxaux</span> + <span class=\"nc-blue_bg\">sacrum</span> + <span class=\"nc-blue_bg\">coccyx</span></li>\n        <li><strong>4 articulations</strong> (très peu mobiles) : <span class=\"nc-blue_bg\">2 articulations sacro-iliaques</span> + <span class=\"nc-blue_bg\">symphyse pubienne</span> + <span class=\"nc-blue_bg\">articulation sacro-coccygienne</span></li>\n      </ul>\n\n      <h4>Filière pelvienne — 3 étages</h4>\n\n      <table>\n        <thead>\n          <tr><th>Étage</th><th>Repères &amp; diamètres</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Détroit supérieur (DS)</strong><br><em>= <span class=\"nc-blue nc-bold\">cylindre d’engagement</span> de Demelin</em></td>\n            <td>\n              <strong>Limites :</strong>\n              <ul>\n                <li>Avant : <span class=\"nc-blue_bg\">bord supérieur de la symphyse pubienne</span></li>\n                <li>Arrière : <span><span class=\"nc-blue_bg\">promontoire</span></span> (disque vertébral L5–S1, <span>9 cm</span> au-dessus de SP)</li>\n                <li>Latéralement : <span class=\"nc-blue_bg\">lignes innominées</span></li>\n              </ul>\n              <strong>Forme :</strong> cœur de carte à jouer (rétréci en sagittal par la saillie du promontoire)<br>\n              <strong>Diamètres :</strong>\n              <ul>\n                <li>Promonto-rétropubien : <span><span class=\"nc-pink nc-bold\">10,5 cm</span></span></li>\n                <li>Transverse médian : <span><span class=\"nc-pink nc-bold\">12,5 cm</span></span></li>\n              </ul>\n              <strong>Axe :</strong> oblique en arrière et en bas, vise l’interligne sacro-coccygien\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Excavation pelvienne</strong><br><em>= canal pelvien / petit bassin</em></td>\n            <td>\n              <strong>Limites :</strong>\n              <ul>\n                <li>Hautes/basses : entre <span class=\"nc-blue nc-bold\">cylindre d’engagement</span> et détroit inférieur</li>\n                <li>Avant/arrière : <span class=\"nc-blue nc-bold\">symphyse pubienne</span> ↔ <span class=\"nc-blue nc-bold\">face antérieure du sacrum</span></li>\n                <li>Latéralement : <span class=\"nc-blue nc-bold\">face interne de l’os iliaque</span> + relief des <strong><span class=\"nc-blue_bg nc-bold\">épines</span> <span class=\"nc-blue_bg nc-bold\">sciatiques</span></strong></li>\n              </ul>\n              <strong>Diamètres :</strong>\n              <ul>\n                <li>Constant à tous les plans : <span>≈ <span class=\"nc-pink nc-bold\">12 cm</span></span></li>\n                <li>Bisciatique/biépineux : <span><span class=\"nc-pink nc-bold\">10,5 cm</span></span> (<em>≠ bi-ischiatique</em>)</li>\n              </ul>\n              <strong>Détroit moyen :</strong> à l’union du 1/3 inférieur et des 2/3 supérieurs, passe par les 2 épines sciatiques<br>\n              <strong>Forme :</strong> cylindre coudé (segment de tore) avec 2 rétrécissements (promontoire + épines sciatiques)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Détroit inférieur (DI)</strong><br><em>= plan de dégagement</em></td>\n            <td>\n              <strong>Forme :</strong> prisme triangulaire\n              <ul>\n                <li>Face supérieure : plan du détroit moyen</li>\n                <li>Face <span class=\"nc-blue_bg nc-bold\">antérieure</span> : oblique bas/arrière, joint bord inférieur du pubis aux ischions</li>\n                <li>Face <span class=\"nc-blue_bg nc-bold\">postérieure</span> : oblique haut/arrière, déterminée par les 2 ischions et la pointe du coccyx</li>\n              </ul>\n              <strong><span>Diamètre</span> bi-ischiatique :</strong> <span>12 cm</span> (principale mesure ; <em>≠ bi-sciatique</em>)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Périnée — diaphragme pelvi-périnéal</h4>\n\n      <ul>\n        <li><span class=\"nc-pink_bg\">Bassin mou</span> = <strong><span class=\"nc-pink_bg\">vagin</span> + diaphragme pelvi-périnéal</strong></li>\n        <li><span class=\"nc-yellow_bg\">Expulsion = traversée du périnée</span> sous l’influence des <span>CU + <span class=\"nc-green nc-bold\">poussée abdominale maternelle</span></span></li>\n        <li><strong>Plan profond :</strong> faisceaux du muscle élévateur de l’anus + ligament sacrotubéral</li>\n        <li><strong>Plan superficiel :</strong> muscles du périnée superficiel</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong><span class=\"nc-yellow_bg\">Présentation</span> engagée.</strong> Une <span class=\"nc-yellow_bg\">présentation</span> est dite engagée lorsque <strong>le plus grand <span>diamètre</span> de la <span class=\"nc-yellow_bg\">présentation</span> a franchi le plan du DS</strong> (= <span class=\"nc-pink nc-bold\">diamètre bipariétal de </span><span><span class=\"nc-pink nc-bold\">9,5 cm</span></span> en <span class=\"nc-yellow_bg\">présentation</span> céphalique).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 25 — <span>Grossesse</span> extra-utérine · 23 — Grossesse normale · 24 — Complications de la grossesse</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Accouchement202017-RPC_HAS-CNGOF_Recommandations.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Accouchement normal, 2017</a></li></ul></details>","frequence":0},{"id":"31-2","rang":"A","rubrique":"Définition","titre":"Connaître les repères du mobile fœtal","contenu":"<div class=\"notion-course\"><p>Le <span>mobile fœtal</span> est un ovoïde à 2 pôles (pelvien + céphalique) pelotonné sur lui-même. Ses dimensions conditionnent la possibilité de franchissement de la filière pelvienne.</p>\n\n      <h4>Tête fœtale</h4>\n\n      <table>\n        <thead>\n          <tr><th>Caractéristique</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Forme</strong></td>\n            <td>Ovoïde — petite extrémité = <strong><span class=\"nc-blue nc-bold\">menton</span></strong>, grosse extrémité = <strong>occiput</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Sutures</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-blue_bg\">Suture longitudinale</span> (sagittale) sur la ligne médiane</li>\n                <li><span class=\"nc-blue_bg\">Sutures transversales antérieure et postérieure</span> (coronale + lambdoïde)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Fontanelles</strong></td>\n            <td>\n              Au croisement entre suture longitudinale et transversale :\n              <ul>\n                <li><span>Fontanelle antérieure</span> = <strong><span class=\"nc-blue nc-bold\">bregma</span></strong> (bregmatique)</li>\n                <li><span>Fontanelle postérieure</span> = <strong><span class=\"nc-blue nc-bold\">lambda</span></strong> (lambdoïde)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Diamètres clés</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"nc-green nc-bold\">Bipariétal</span> :</strong> <span><span class=\"nc-pink nc-bold\">9,5 cm</span></span> — <span>diamètre</span> du passage de la tête</li>\n                <li><span class=\"nc-green nc-bold\">Sous-occipito-bregmatique</span> : <span><span class=\"nc-pink nc-bold\">9,5 cm</span></span> (favorable à l’engagement, tête bien fléchie)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Corps fœtal</h4>\n\n      <table>\n        <thead>\n          <tr><th><span>Diamètre</span></th><th>Valeur</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"nc-yellow_bg\">Biacromial</span></strong></td><td><span><span class=\"nc-pink nc-bold\">12 cm</span></span> réduit à <span>9,5 cm</span> par tassement (passage des épaules)</td></tr>\n          <tr><td>Bitrochantérien</td><td><span>9 cm</span></td></tr>\n          <tr><td>Bi-iliaque</td><td><span>8 cm</span></td></tr>\n          <tr><td>Sacro-pubien</td><td><span>7,5 cm</span></td></tr>\n          <tr><td>Sterno-dorsal</td><td><span>9,5 cm</span></td></tr>\n          <tr><td>Sacro-pré-tibial</td><td><span><span class=\"nc-pink nc-bold\">12 cm</span></span> réduit à <span>9 cm</span> par tassement</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong><span class=\"nc-yellow_bg\">Présentation</span> céphalique fléchie.</strong> Le <span>diamètre</span> céphalique varie selon la flexion. <strong>Tête en flexion maximale</strong> sur le tronc = <span class=\"nc-yellow_bg\">présentation</span> céphalique fléchie = <strong><span class=\"nc-blue_bg\">diamètre bipariétal</span></strong> qui conditionne l’engagement. L’accouchement est d’autant plus facile que la tête est bien fléchie.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span>Grossesse</span> normale · 34 — Suites de couches pathologiques</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Accouchement202017-RPC_HAS-CNGOF_Recommandations.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Accouchement normal, 2017</a></li></ul></details>","frequence":0},{"id":"31-3","rang":"A","rubrique":"Définition","titre":"Connaître les modifications de l’utérus liées à la grossesse et à l’accouchement","contenu":"<div class=\"notion-course\"><p>L’utérus subit des <span>modifications majeures</span> pendant la <span>grossesse</span> pour devenir le moteur de l’accouchement.</p>\n\n      <h4>3 parties de l’utérus gravide</h4>\n\n      <ul>\n        <li><strong>Corps</strong> — forme d’ovoïde à grosse extrémité supérieure en fin de <span>grossesse</span></li>\n        <li><strong>Segment inférieur</strong> — portion <em>propre à la gravidité</em>, <span>absent chez la femme non enceinte</span></li>\n        <li><strong>Col</strong> — contient 2 orifices : externe et interne</li>\n      </ul>\n\n      <h4>Segment inférieur (segment antérieur)</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Formation temporaire.</strong> N’apparaît qu’au <strong>3<sup>e</sup> trimestre</strong>, développé <strong>entre le corps et le col</strong> aux dépens de l’isthme utérin. En fin de travail : mesure <span>10 cm</span>, épaisseur de quelques millimètres seulement.\n        <ul>\n          <li><strong><span class=\"nc-green_bg\">Rôle</span> :</strong> recueille la force de la contraction utérine et la dirige sur le col</li>\n          <li><strong>Peu vascularisé</strong> et limité en haut par la zone de décollement du péritoine vésico-utérin</li>\n          <li><strong>Intérêt chirurgical fondamental :</strong> <span><span class=\"nc-pink nc-bold\">zone d’incision des césariennes segmentaires transversales</span></span></li>\n        </ul>\n      </div>\n\n      <h4>3 tuniques de l’utérus</h4>\n\n      <table>\n        <thead>\n          <tr><th>Tunique</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Séreuse</strong></td>\n            <td>Péritoine, particularité = se clive facilement au niveau du segment inférieur</td>\n          </tr>\n          <tr>\n            <td><strong>Muqueuse</strong></td>\n            <td>Transformée en <span>caduques</span> lors de la <span>grossesse</span></td>\n          </tr>\n          <tr>\n            <td><strong>Musculeuse (myomètre)</strong></td>\n            <td>\n              Fibres musculaires lisses disposées en 2 assises (externe + interne) de part et d’autre d’une <strong>couche plexiforme</strong> dont les faisceaux enserrent de nombreux vaisseaux.\n              <ul>\n                <li>Couche circulaire externe + faisceaux longitudinaux discontinus</li>\n                <li><span>Phénomène des ligatures vivantes</span> = la rétraction des fibres efface la lumière des vaisseaux au niveau de la couche plexiforme → <strong>réduit l’hémorragie de la délivrance</strong></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Axe &amp; dextrorotation</h4>\n\n      <ul>\n        <li><strong>Axe du corps utérin :</strong> en décubitus, axe de poussée utérine légèrement incliné vers l’avant par rapport à l’axe du DS</li>\n        <li><strong>Dextrorotation :</strong> dans le plan frontal, l’utérus est fréquemment incliné <strong>du côté droit</strong> (rotation sur axe vertical, face <span class=\"nc-blue_bg nc-bold\">antérieure</span> dirigée en avant et à droite)</li>\n      </ul>\n\n      <h4><span class=\"nc-yellow_bg\">Modifications du col</span> utérin</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Effacement puis dilatation.</strong>\n        <ul>\n          <li><strong><span class=\"nc-yellow_bg\">Effacement du col</span> :</strong> disparition progressive de <span class=\"nc-red nc-bold\">l’épaisseur</span> et de la <span class=\"nc-red nc-bold\">longueur</span> du col</li>\n          <li><strong><span class=\"nc-green nc-bold\">Dilatation</span> :</strong> orifice cervical s’élargit jusqu’à <span><span class=\"nc-red nc-bold\">10 cm</span></span> (<span class=\"nc-green nc-bold\">dilatation</span> complète)</li>\n          <li><span class=\"nc-green nc-bold\">Chez la </span><span><span class=\"nc-green nc-bold\">multipare</span></span> : <span class=\"nc-green nc-bold\">effacement et dilatation s’effectuent </span><strong><span class=\"nc-green nc-bold\">en même temps</span> ⭐</strong></li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span>Grossesse</span> normale · 34 — Suites de couches pathologiques</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Accouchement202017-RPC_HAS-CNGOF_Recommandations.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Accouchement normal, 2017</a></li></ul></details>","frequence":0},{"id":"31-4","rang":"A","rubrique":"Définition","titre":"Connaître le rôle des contractions utérines et la manière de les surveiller","contenu":"<div class=\"notion-course\"><p>Les <span><span class=\"nc-yellow_bg\">contractions utérines</span> (CU)</span> sont le <strong>moteur de l’accouchement</strong>. Elles assurent la <span class=\"nc-blue nc-bold\">dilatation</span> du col, la formation de la poche des eaux, et la <span class=\"nc-pink\">progression</span> du mobile fœtal.</p>\n\n      <h4>Caractéristiques des CU du travail</h4>\n\n      <ul>\n        <li><strong><span class=\"nc-green_bg\">Totales</span></strong> — intéressent tout l’utérus</li>\n        <li><strong><span class=\"nc-green_bg\">Involontaires</span></strong></li>\n        <li><strong>Intermittentes / répétées / rapprochées</strong> — chaque contraction précédée et suivie d’une période de repos</li>\n        <li><strong>Progressives</strong> dans leur durée, fréquence et intensité</li>\n        <li><strong><span class=\"nc-blue_bg\">Douloureuses</span></strong> — <span><span class=\"nc-pink nc-bold\">analgésie péridurale</span></span> = moyen le plus efficace pour les supprimer</li>\n      </ul>\n\n      <h4>Rôles physiologiques des CU</h4>\n\n      <table>\n        <thead>\n          <tr><th>Cible</th><th>Effet</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Col utérin</strong></td>\n            <td>\n              <ol>\n                <li><strong><span class=\"nc-yellow_bg\">Effacement</span></strong><span class=\"nc-yellow_bg\"> du col</span> : disparition progressive de <span class=\"nc-red nc-bold\">l’épaisseur</span> et de la <span class=\"nc-red nc-bold\">longueur</span></li>\n                <li><strong><span class=\"nc-green nc-bold\">Dilatation</span></strong> : élargissement progressif jusqu’à <span><span class=\"nc-red nc-bold\">10 cm</span></span></li>\n              </ol>\n              Chez la <span>multipare</span> : effacement et dilatation simultanés ⭐\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Poche des eaux</strong></td>\n            <td>\n              Constitution par décollement des membranes au cours du travail. <strong>Double rôle :</strong>\n              <ul>\n                <li><span class=\"nc-green_bg\">Protecteur</span> : œuf <span>vs</span> <strong><span class=\"nc-green nc-bold\">infection</span></strong>, fœtus <span>vs</span> <strong><span class=\"nc-green nc-bold\">traumatisme</span></strong></li>\n                <li><span class=\"nc-green_bg\">Mécanique</span> : <strong><span class=\"nc-green nc-bold\">aide à la dilatation cervicale</span></strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Mobile fœtal</strong></td>\n            <td>Permet le franchissement des étages de la filière pelvi-génitale (DS → excavation → DI → périnée)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span>Surveillance</span> des CU — <span class=\"nc-blue_bg\">Tocographie</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Méthode</th><th>Apport</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Tocographie externe</strong></td>\n            <td>Capteur externe → note la <strong>durée</strong> et la <strong>fréquence</strong> des CU</td>\n          </tr>\n          <tr>\n            <td><strong>Tocographie interne</strong></td>\n            <td>\n              Cathéter fin et souple introduit par voie transcervicale dans la cavité utérine →\n              <ul>\n                <li><strong>Tonus de base</strong></li>\n                <li><strong>Pression intra-utérine</strong></li>\n              </ul>\n              Peut être intra- ou extra-amniotique selon que les membranes sont rompues\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Cardiotocographie (CTG)</strong></td>\n            <td>Enregistrement <strong>simultané</strong> du <span>RCF</span> + des CU — continu pendant les 2 premières étapes</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Anomalies des CU à reconnaître.</strong>\n        <ul>\n          <li><span>Hypocinésie</span> — CU insuffisantes (fréquence/intensité)</li>\n          <li><span>Hypercinésie</span> — CU excessives</li>\n          <li><span>Hypotonie</span> — tonus de base trop bas</li>\n          <li><span>Hypertonie</span> — tonus de base trop élevé (risque d’<strong><span>hypoxie fœtale</span></strong>)</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 24 — Complications de la <span>grossesse</span></em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Accouchement202017-RPC_HAS-CNGOF_Recommandations.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Accouchement normal, 2017</a></li></ul></details>","frequence":0},{"id":"31-5","rang":"A","rubrique":"Définition","titre":"Connaître les définitions des différents types d’accouchement","contenu":"<div class=\"notion-course\"><p>L’<span>accouchement</span> = ensemble des phénomènes aboutissant à l’expulsion du fœtus et des annexes hors du ventre maternel (fœtus + placenta + liquide amniotique + membranes).</p>\n\n      <h4>Définitions fondamentales</h4>\n\n      <ul>\n        <li><strong>Accouchement normal</strong> = débute <span>spontanément</span> (≠ déclenchement du travail)</li>\n        <li>Le fœtus doit franchir <strong>3 obstacles</strong> : <span>col utérin</span> + <span>bassin</span> + <span>périnée</span></li>\n        <li>Les <strong><span class=\"nc-yellow_bg\">contractions utérines</span></strong> sont le moteur de l’accouchement</li>\n      </ul>\n\n      <h4>Eutocique <span>vs</span> <span class=\"nc-red nc-bold\">Dystocique</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Type</th><th>Définition</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Eutocique</strong></td>\n            <td>Expulsion par <strong>voie basse</strong> par la <em>seule influence des phénomènes naturels</em></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-red nc-bold\">Dystocique</span></strong></td>\n            <td>Entraîne des <span>difficultés ou impossibilités d’accouchement par voie basse</span> (nécessite manœuvres instrumentales ou césarienne)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Spontané <span>vs</span> Déclenché</h4>\n\n      <ul>\n        <li><strong>Accouchement spontané</strong> — travail démarre de lui-même</li>\n        <li><strong>Accouchement déclenché</strong> — induction du travail pour raison médicale (dépassement de terme, RPM, pathologie maternelle ou fœtale)</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Voies de naissance.</strong>\n        <ul>\n          <li><span>Voie basse</span> — accouchement vaginal (eutocique ou avec extraction instrumentale : forceps, ventouse, spatules)</li>\n          <li><span>Voie haute</span> — <strong>césarienne</strong> (programmée ou en <span>urgence</span>)</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 24 — Complications de la <span>grossesse</span></em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Accouchement202017-RPC_HAS-CNGOF_Recommandations.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Accouchement normal, 2017</a></li></ul></details>","frequence":0},{"id":"31-6","rang":"A","rubrique":"Définition","titre":"Connaître les différentes étapes de l’accouchement","contenu":"<div class=\"notion-course\"><p>L’accouchement se déroule en <span>4 étapes</span> séquentielles. Connaître leur succession et leur durée est indispensable pour suivre la progression du travail.</p>\n\n      <h4>Vue d’ensemble — 4 étapes</h4>\n\n      <table>\n        <thead>\n          <tr><th>Étape</th><th>Début</th><th>Fin</th><th>Durée</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1<sup>re</sup> étape</strong><br><em>Dilatation du col</em></td>\n            <td>Début du vrai travail</td>\n            <td><span class=\"nc-green nc-bold\">Dilatation</span> complète (<span><span class=\"nc-red nc-bold\">10 cm</span></span>)</td>\n            <td>\n              <ul>\n                <li>Primipare : <span>6–18 h</span></li>\n                <li>Multipare : <span>2–10 h</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>2<sup>e</sup> étape</strong><br><em>Expulsion</em></td>\n            <td>Fin de la <span class=\"nc-green nc-bold\">dilatation</span> du col</td>\n            <td><span class=\"nc-yellow_bg\">Naissance de l’enfant</span></td>\n            <td><span>3–4 h maximum</span></td>\n          </tr>\n          <tr>\n            <td><strong>3<sup>e</sup> étape</strong><br><em>Délivrance</em></td>\n            <td><span class=\"nc-yellow_bg\">Naissance de l’enfant</span></td>\n            <td>Expulsion du placenta et des membranes</td>\n            <td><span>5–30 min</span></td>\n          </tr>\n          <tr>\n            <td><strong>4<sup>e</sup> étape</strong><br><em>Post-partum immédiat</em></td>\n            <td>Délivrance</td>\n            <td>Stabilisation des constantes maternelles</td>\n            <td><span>2 h</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Découpage du 1<sup>er</sup> <span>stade</span></h4>\n\n      <ul>\n        <li><strong>Phase de latence</strong> — début du travail jusqu’à <span class=\"nc-green nc-bold\">dilatation</span> cervicale de <span>5–6 cm</span></li>\n        <li><strong>Phase active</strong> — de <span>5–6 cm</span> jusqu’à <span class=\"nc-green nc-bold\">dilatation</span> complète (<span><span class=\"nc-red nc-bold\">10 cm</span></span>)</li>\n      </ul>\n\n      <h4>Découpage du 2<sup>e</sup> <span>stade</span></h4>\n\n      <ul>\n        <li><strong>Phase de descente</strong> (passive) — de la <span class=\"nc-green nc-bold\">dilatation</span> complète jusqu’au début des <span class=\"nc-brown_bg\">efforts expulsifs</span></li>\n        <li><strong>Phase d’expulsion</strong> (active) — entre le début des <span class=\"nc-brown_bg\">efforts expulsifs</span> et la naissance</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Influence de la parité.</strong> La durée du travail est plus longue chez les <span>nullipares</span> que chez les <span>multipares</span>. Chez une même femme, la durée se raccourcit avec la parité. <span>Grande <span class=\"nc-green nc-bold\">multipare</span> → risque d’accouchement à domicile</span> (travail très rapide).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : obj-6 (description détaillée des étapes)</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Accouchement202017-RPC_HAS-CNGOF_Recommandations.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Accouchement normal, 2017</a></li></ul></details>","frequence":0},{"id":"31-7","rang":"B","rubrique":"Définition","titre":"Connaître la description des différentes étapes du travail","contenu":"<div class=\"notion-course\"><p>La description détaillée du travail comporte <span>3 stades</span> obstétricaux, avec des phases internes définissant la cinétique de la dilatation et de la descente fœtale.</p>\n\n      <h4>1<sup>er</sup> <span>stade</span> — Dilatation du col</h4>\n\n      <div class=\"callout callout-info\">\n        <strong><span>Diagnostic positif</span> du début du travail.</strong> Association de :\n        <ul>\n          <li><strong><span class=\"nc-yellow_bg\">Modifications du col</span> :</strong> <span class=\"nc-red nc-bold\">raccourcissement</span>, ramollissement, <span class=\"nc-red nc-bold\">ouverture jusqu’à dilatation complète</span> (<span><span class=\"nc-red nc-bold\">10 cm</span></span>)</li>\n          <li><strong>CU du travail</strong> (par interrogatoire / palpation / <span class=\"nc-blue_bg\">tocographie</span>) : <span class=\"nc-green_bg\">totales</span>, <span class=\"nc-green_bg\">involontaires</span>, intermittentes/répétées, progressives, <span class=\"nc-blue_bg\">douloureuses</span></li>\n        </ul>\n      </div>\n\n      <p><span><span class=\"nc-blue_bg\">Perte du « bouchon muqueux »</span></span><span class=\"nc-blue_bg\"> précède souvent le début du travail</span> (écoulement de <strong><span class=\"nc-blue nc-bold\">glaires épaisses et brunâtres</span></strong> par la vulve).</p>\n\n      <table>\n        <thead>\n          <tr><th>Phase</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Phase de latence</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-green nc-bold\">Dilatation</span> jusqu’à <span>5–6 cm</span></li>\n                <li>Succède à l’effacement (parallèle <span class=\"nc-green nc-bold\">chez la multipare</span> ⭐)</li>\n                <li>Début du travail = <strong>&gt; 2 CU pour <span>10 min</span></strong></li>\n                <li>Phase <strong>la plus longue</strong> (parfois <span class=\"nc-pink nc-bold\">&gt; </span><span><span class=\"nc-pink nc-bold\">10 h</span></span> chez la nullipare)</li>\n                <li><em>Ancien réf. :</em> moyenne <span>8,5 h</span> primipare / <span>5,5 h</span> multipare ; max <span>20 h</span> / <span>14 h</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Phase active</strong></td>\n            <td>\n              Après <span>5–6 cm</span>, vitesse de dilatation <span>anormale</span> ⚠️ si :\n              <ul>\n                <li>Entre <span>5–7 cm</span> : <strong><span class=\"nc-red nc-bold\">&lt; </span><span><span class=\"nc-red nc-bold\">1 cm</span></span><span class=\"nc-red nc-bold\"> / </span><span><span class=\"nc-red nc-bold\">4 h</span></span></strong></li>\n                <li>Entre <span>7 cm</span> et dilatation complète : <strong><span class=\"nc-red nc-bold\">&lt; </span><span><span class=\"nc-red nc-bold\">1 cm</span></span><span class=\"nc-red nc-bold\"> / </span><span><span class=\"nc-red nc-bold\">2 h</span></span></strong></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Poche des eaux — types de <span>rupture</span></h4>\n\n      <ul>\n        <li><strong>Spontanée</strong> — pendant le travail, sans intervention</li>\n        <li><strong>Artificielle (<span>amniotomie</span>)</strong> — <span>rupture</span> volontaire pour aider le travail (stagnation de la dilatation avec membranes intactes)</li>\n        <li><strong>Tempestive</strong> — à dilatation complète</li>\n        <li><strong>Intempestive</strong> — avant dilatation complète</li>\n        <li><span><strong>Prématurée (RPM)</strong></span> — <strong>avant tout travail</strong>, <strong><span class=\"nc-red nc-bold\">risque </span><span><span class=\"nc-red nc-bold\">infectieux</span></span> ⚠️</strong></li>\n      </ul>\n\n      <h4>2<sup>e</sup> <span>stade</span> — Naissance</h4>\n\n      <ul>\n        <li><strong>Phase de descente (passive)</strong> — de la <span class=\"nc-green nc-bold\">dilatation</span> complète jusqu’au début des <span class=\"nc-brown_bg\">efforts expulsifs</span></li>\n        <li><strong>Phase d’expulsion (active)</strong> — du début des <span class=\"nc-brown_bg\">efforts expulsifs</span> jusqu’à la naissance</li>\n      </ul>\n\n      <h4>3<sup>e</sup> <span>stade</span> — Délivrance</h4>\n\n      <p>De la <span class=\"nc-yellow_bg\">naissance de l’enfant</span> jusqu’à l’expulsion du placenta. Durée normale : <span>5–30 min</span>. Au-delà de <span>30 min</span> → <span class=\"nc-yellow_bg\">délivrance</span> artificielle.</p>\n\n      <h4><span>Surveillance</span> — <span>antibioprophylaxie</span> SGB</h4>\n\n      <div class=\"callout callout-info\">\n        <strong><span>Antibioprophylaxie</span> SGB</strong> chez les femmes à risque (portage <span>Streptocoque B</span>) : <span>pénicilline G</span>, <span>amoxicilline</span>, <span>ampicilline</span> ou <span>céfazoline</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : obj-5 (vue d’ensemble étapes) · obj-12 (délivrance)</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Accouchement202017-RPC_HAS-CNGOF_Recommandations.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Accouchement normal, 2017</a></li></ul></details>","frequence":0},{"id":"31-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments de surveillance clinique de l’accouchement normal","contenu":"<div class=\"notion-course\"><p>La <span>surveillance</span> clinique de l’accouchement repose sur un faisceau d’éléments cliniques et paracliniques reportés sur le <span><span class=\"nc-blue nc-bold\">partogramme</span></span>, <span class=\"nc-pink nc-bold\">au minimum </span><strong><span class=\"nc-pink nc-bold\">toutes les heures</span></strong>.</p>\n\n      <h4>Examen clinique maternel</h4>\n\n      <table>\n        <thead>\n          <tr><th>Élément</th><th>Modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Analgésie</strong></td>\n            <td>Anesthésie péridurale possible en <span class=\"nc-yellow_bg nc-bold\">début de travail</span></td>\n          </tr>\n          <tr>\n            <td><strong>Abdomen</strong></td>\n            <td>Palpation = présentation fœtale (longitudinale/transversale) par recherche du pôle céphalique et du plan du dos</td>\n          </tr>\n          <tr>\n            <td><strong>Hauteur utérine</strong></td>\n            <td>Mesurée <strong>en dehors d’une CU</strong> — moyenne <span><span class=\"nc-pink nc-bold\">33 cm</span></span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-blue_bg\">Toucher vaginal</span> (<span>TV</span>)</strong></td>\n            <td>\n              Réalisé avec asepsie <strong>toutes les <span>30 min</span> à <span>1 h</span></strong>. Renseigne sur :\n              <ul>\n                <li>Diagnostic et variété de présentation</li>\n                <li>État de la poche des eaux (présence ou non de membranes)</li>\n                <li>État du col par <span>score de Bishop</span> : <strong><span class=\"nc-blue nc-bold\">dilatation</span> · <span class=\"nc-blue nc-bold\">effacement</span> · <span class=\"nc-blue nc-bold\">consistance</span> · <span class=\"nc-blue nc-bold\">position</span> du col · <span class=\"nc-blue nc-bold\">positionnement</span> de la présentation fœtale</strong> (5 critères)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span>Score</span> de Bishop</h4>\n\n      <div class=\"callout callout-info\">\n        <strong><span>Score</span> de Bishop</strong> — évalue la <strong>maturation du col</strong> en 5 critères côtés 0–2 ou 0–3 (sur 13). Détermine l’éligibilité au déclenchement du travail.\n      </div>\n\n      <h4>Poche des eaux &amp; liquide amniotique</h4>\n\n      <table>\n        <thead>\n          <tr><th>Situation</th><th>CAT</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Membranes intactes</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"nc-green_bg\">Conservation</span></strong><span class=\"nc-green_bg\"> de l’intégrité de la poche des eaux</span>, OU</li>\n                <li><strong><span>Rupture</span> artificielle</strong> si <span><span class=\"nc-blue nc-bold\">dilatation</span> <span class=\"nc-pink nc-bold\">&gt; 6 cm</span></span> ET <strong>présentation engagée</strong></li>\n                <li>Après <span>rupture</span> : <span>réexaminer la parturiente pour vérifier l’absence de <span class=\"nc-red nc-bold\">procidence du cordon</span></span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>RPM</strong> (<span><span class=\"nc-red_bg\">rupture</span></span><span class=\"nc-red_bg\"> prématurée</span>)</td>\n            <td>\n              Pas de poche des eaux. Risques :\n              <ul>\n                <li><span>Infection</span></li>\n                <li><span><span class=\"nc-red nc-bold\">Procidence du cordon</span></span> (cordon ombilical devant la présentation)</li>\n              </ul>\n              CAT : <strong><span>hospitalisation</span> immédiate 🏥</strong>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Couleur du liquide amniotique</h4>\n\n      <ul>\n        <li><strong>Normale</strong> — <span class=\"nc-green nc-bold\">clair</span>, <span class=\"nc-green nc-bold\">transparent</span>, <span class=\"nc-green nc-bold\">lactescent</span></li>\n        <li><strong>Épais ou teinté</strong> — en faveur d’une <span><span class=\"nc-red nc-bold\">chorioamniotite</span></span></li>\n        <li><strong>Vert ± sombre (méconial)</strong> — <span><span class=\"nc-red nc-bold\">signe d’état fœtal non rassurant</span></span> (toute émission de méconium avant l’accouchement traduit une pathologie)</li>\n      </ul>\n\n      <h4><span>Surveillance</span> fœtale</h4>\n\n      <ul>\n        <li><strong><span>Échographie</span></strong> en salle de travail : confirme l’examen obstétrical, estime la quantité de LA, localise le placenta, confirme la présentation</li>\n        <li><strong>Cardiotocographe (CTG)</strong> — enregistrement <strong>simultané</strong> :\n          <ul>\n            <li><span>RCF</span> — <strong>continu pendant les 2 premières étapes</strong></li>\n            <li><span><span class=\"nc-blue_bg\">Tocographie</span></span> — caractéristiques des CU (anomalies = hypocinésie, hypercinésie, hypotonie, hypertonie)</li>\n          </ul>\n        </li>\n        <li><strong><span><span class=\"nc-blue_bg\">ECG</span></span><span class=\"nc-blue_bg\"> fœtal</span></strong> ou <strong><span><span class=\"nc-blue_bg\">pH au scalp</span></span></strong> — autres moyens de <span>surveillance</span> fœtale</li>\n      </ul>\n\n      <h4><span>Surveillance</span> du 4<sup>e</sup> <span>stade</span></h4>\n\n      <div class=\"callout callout-warn\">\n        <strong>Post-partum immédiat — <span>2 h</span> en salle de travail.</strong>\n        <ul>\n          <li><span>Surveillance</span> <strong>constante</strong> de l’accouchée pendant <span><span class=\"nc-pink nc-bold\">2 h après la délivrance</span></span></li>\n          <li><strong><span class=\"nc-blue_bg\">Expression utérine</span></strong> 2–3 fois : <em><span class=\"nc-blue nc-bold\">empaumer l’utérus à pleine main</span> et appuyer vers le bas</em> → évacue les caillots situés dans l’utérus et le vagin</li>\n        </ul>\n      </div>\n\n      <h4>Prévention de l’allo-immunisation Rh</h4>\n\n      <table>\n        <thead>\n          <tr><th>Situation</th><th>CAT</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Phénotype <span>RhD</span> du nouveau-né non connu</strong></td>\n            <td><span class=\"nc-blue_bg\">Contrôle du groupe Rh sur sang du cordon</span></td>\n          </tr>\n          <tr>\n            <td><strong>Mère Rh+ confirmé au <span>génotypage de grossesse</span></strong></td>\n            <td><span><span class=\"nc-red nc-bold\">Aucun contrôle supplémentaire</span></span></td>\n          </tr>\n          <tr>\n            <td><strong>Mère Rh− + enfant Rh−</strong></td>\n            <td>Rien à faire après contrôle</td>\n          </tr>\n          <tr>\n            <td><strong>Mère Rh− + enfant Rh+</strong></td>\n            <td>\n              <ol>\n                <li><strong><span>Test de Kleihauer</span></strong> sur sang maternel <strong><span>≥ 30 min</span> après la délivrance</strong></li>\n                <li><strong><span class=\"nc-pink_bg\">Prophylaxie anti-D</span></strong><span class=\"nc-pink_bg\"> chez la mère dans les</span> <span><span class=\"nc-pink_bg nc-bold\">&lt; 72 h</span></span> (posologie ajustée au Kleihauer)</li>\n                <li>Injection possible <strong><span class=\"nc-pink nc-bold\">jusqu’à </span><span><span class=\"nc-pink nc-bold\">30 jours</span></span><span class=\"nc-pink nc-bold\"> après l’accouchement</span></strong> si oubli <span class=\"nc-pink_bg nc-bold\">&lt; </span><span><span class=\"nc-pink_bg nc-bold\">72 h</span></span></li>\n              </ol>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span>Grossesse</span> normale · 24 — Complications de la grossesse</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Accouchement202017-RPC_HAS-CNGOF_Recommandations.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Accouchement normal, 2017</a></li></ul></details>","frequence":0},{"id":"31-9","rang":"B","rubrique":"Contenu multimédia","titre":"Engagement de la tête fœtale","contenu":"<div class=\"notion-course\"><p>L’<span>engagement</span> = <strong><span class=\"nc-yellow_bg\">franchissement du DS par le plus grand </span><span><span class=\"nc-yellow_bg\">diamètre</span></span><span class=\"nc-yellow_bg\"> de la présentation</span></strong>. C’est le 1<sup>er</sup> temps de la traversée de la filière pelvienne et l’étape qui conditionne le plus souvent la possibilité d’accouchement par voie basse.</p>\n\n      <h4>Définition opérationnelle</h4>\n\n      <div class=\"callout callout-info\">\n        <strong><span class=\"nc-yellow_bg\">Présentation</span> engagée</strong> = sa <strong>plus grande circonférence</strong> a franchi le DS. En <span class=\"nc-yellow_bg\">présentation</span> céphalique fléchie, cela correspond au passage du <span><span class=\"nc-pink nc-bold\">diamètre bipariétal de 9,5 cm</span></span>.\n      </div>\n\n      <h4>Accommodation de la tête fœtale au DS — 4 opérations</h4>\n\n      <ol>\n        <li><strong><span class=\"nc-green_bg\">Flexion du sommet</span></strong> — les dimensions les plus favorables sont <strong><span class=\"nc-green nc-bold\">sous-occipito-bregmatique</span> + <span class=\"nc-green nc-bold\">bipariétal</span></strong></li>\n        <li><strong><span class=\"nc-green_bg\">Orientation en oblique</span></strong> — les diamètres les plus utilisables du DS sont les <strong><span class=\"nc-green nc-bold\">diamètres obliques</span></strong></li>\n        <li><strong>Asynclitisme</strong> — inclinaison latérale (facultatif)</li>\n        <li><strong><span class=\"nc-brown_bg\">Déformations plastiques</span></strong> — modelage de la tête (facultatif)</li>\n      </ol>\n\n      <h4>Forces en jeu (ancien référentiel)</h4>\n\n      <ul>\n        <li>Force de poussée (P) de la CU fait avec l’axe du DS un angle de <span>30–50°</span></li>\n        <li>P se décompose en :\n          <ul>\n            <li><strong>Force de <span class=\"nc-pink\">progression</span> (G)</strong> — perpendiculaire à l’axe du DS</li>\n            <li><strong>Force de <span class=\"nc-pink\">résistance</span> (R)</strong> — parallèle à l’axe, participe à la flexion et à l’<span class=\"nc-green_bg\">orientation en oblique</span></li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4>Diagnostic clinique de l’engagement</h4>\n\n      <table>\n        <thead>\n          <tr><th>Type d’examen</th><th>Signes</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Symptômes maternels</strong></td>\n            <td><span class=\"nc-green_bg\">Femme respire plus librement</span> (mobile descendu), mais <span class=\"nc-blue_bg\">gêne s’accentue du côté des organes pelviens</span></td>\n          </tr>\n          <tr>\n            <td><strong>Hauteur utérine</strong></td>\n            <td><strong><span class=\"nc-pink nc-bold\">Diminué de quelques centimètres</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong>Palpation abdominale</strong></td>\n            <td>\n              <ul>\n                <li><strong><span><span class=\"nc-yellow_bg\">Signe de Le Lorier</span></span></strong> — engagée si <strong><span class=\"nc-pink nc-bold\">2 doigts</span></strong> ne tiennent pas entre <span class=\"nc-blue nc-bold\">épaule antérieure du fœtus</span> et <span class=\"nc-blue nc-bold\">bord supérieur du pubis</span></li>\n                <li><strong><span><span class=\"nc-yellow_bg\">Signe de Favre</span></span></strong> — engagée si distance épaule <span class=\"nc-blue_bg nc-bold\">antérieure</span> ↔ <span class=\"nc-blue nc-bold\">bord supérieur du pubis</span> <span class=\"nc-pink nc-bold\">&lt; </span><span><span class=\"nc-pink nc-bold\">7 cm</span></span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-blue_bg\">Toucher vaginal</span></strong></td>\n            <td>\n              <ul>\n                <li><strong><span><span class=\"nc-yellow_bg\">Signe de Farabeuf</span></span></strong> — engagée si <strong><span class=\"nc-pink nc-bold\">2 doigts</span></strong> seulement entre pôle céphalique et plan sacro-coccygien</li>\n                <li><strong><span><span class=\"nc-yellow_bg\">Signe de Demelin</span></span></strong> — engagée si index introduit perpendiculairement à la face <span class=\"nc-blue_bg nc-bold\">antérieure</span> de la SP, parallèlement à son bord inférieur, <strong>vient buter contre la présentation</strong></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Position par rapport aux <span class=\"nc-blue_bg nc-bold\">épines</span> <span class=\"nc-blue_bg nc-bold\">sciatiques</span></h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Référentiel des épines sciatiques.</strong>\n        <ul>\n          <li><span>Niveau 0</span> — sommet au niveau des <span class=\"nc-blue_bg nc-bold\">épines</span> = <strong>tête fœtale engagée</strong></li>\n          <li><span>Niveaux –1 à –5</span> — sommet <span>1 à 5 cm</span> <strong>au-dessus</strong> du plan des <span class=\"nc-blue_bg nc-bold\">épines</span></li>\n          <li><span>Niveaux +1 à +5</span> — sommet <span>1 à 5 cm</span> <strong>en-dessous</strong> du plan des <span class=\"nc-blue_bg nc-bold\">épines</span></li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-warn\">Repère de lecture : l’occiput oriente la variété de <span class=\"nc-blue nc-bold\">position</span> ; flexion, engagement <span class=\"nc-blue_bg\">puis</span> descente et rotation sont des phénomènes distincts. Les détails sont reliés au parcours interactif de l’accouchement.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : obj-9 (orientation) · obj-1 (mobile fœtal)</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Accouchement202017-RPC_HAS-CNGOF_Recommandations.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Accouchement normal, 2017</a></li></ul></details>","frequence":0},{"id":"31-10","rang":"B","rubrique":"Contenu multimédia","titre":"Orientation de la tête fœtale","contenu":"<div class=\"notion-course\"><p>L’<span>orientation</span> = position d’engagement définie par l’orientation à <strong>gauche / droite</strong> et <strong><span class=\"nc-blue_bg nc-bold\">antérieure</span> / <span class=\"nc-blue_bg nc-bold\">postérieure</span></strong> du dos du fœtus (occiput = repère). Les <span class=\"nc-green nc-bold\">diamètres obliques</span> du DS sont les plus utilisables.</p>\n\n      <h4>Position d’engagement — variétés</h4>\n\n      <table>\n        <thead>\n          <tr><th>Variété</th><th>Sigle</th><th>Fréquence</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Occipito-iliaque gauche antérieure</td><td><strong><span class=\"nc-yellow_bg\">OIGA</span></strong> ⭐</td><td><span>57 %</span> — <strong>la plus fréquente d’engagement</strong></td></tr>\n          <tr><td>Occipito-iliaque droite postérieure</td><td><strong><span class=\"nc-yellow_bg\">OIDP</span></strong></td><td><span>33 %</span></td></tr>\n          <tr><td>Occipito-iliaque gauche postérieure</td><td>OIGP</td><td><span>6 %</span></td></tr>\n          <tr><td>Occipito-iliaque droite antérieure</td><td>OIDA</td><td><span>4 %</span></td></tr>\n          <tr><td>Occipito-iliaque gauche transverse</td><td><span class=\"nc-red\">OIGT</span></td><td>variété accessoire</td></tr>\n          <tr><td>Occipito-iliaque droite transverse</td><td><span class=\"nc-red\">OIDT</span></td><td>variété accessoire</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Ne pas confondre — Engagement <span>vs</span> Dégagement.</strong>\n        <ul>\n          <li>Présentation d’<strong>engagement</strong> : <span>OIGA</span> (la plus fréquente)</li>\n          <li>Présentation de <strong>dégagement</strong> : <span>OP</span> (occipito-pubienne, la plus fréquente)</li>\n        </ul>\n        📝 Piège classique en obstétrique — facile d’inverser engagement et dégagement.\n      </div>\n\n      <h4>Types de présentation et diamètres</h4>\n\n      <table>\n        <thead>\n          <tr><th>Présentation</th><th>Repère</th><th><span>Diamètre</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Sommet</strong> (tête hyperfléchie)</td>\n            <td>Occiput</td>\n            <td><span class=\"nc-green nc-bold\">Bipariétal</span> — <span><span class=\"nc-pink nc-bold\">9,5 cm</span></span></td>\n          </tr>\n          <tr>\n            <td><strong>Face</strong> (tête totalement défléchie)</td>\n            <td><span class=\"nc-blue nc-bold\">Menton</span></td>\n            <td>Sous-mento-bregmatique — <span><span class=\"nc-pink nc-bold\">9,5 cm</span></span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-red nc-bold\">Front</span></strong> (flexion intermédiaire)</td>\n            <td>Nez</td>\n            <td>Syncipito-mentonnier — <span><span class=\"nc-red nc-bold\">césarienne requise</span></span></td>\n          </tr>\n          <tr>\n            <td><strong>Bregma</strong> (flexion intermédiaire)</td>\n            <td>—</td>\n            <td>Occipito-frontal</td>\n          </tr>\n          <tr>\n            <td><strong>Siège</strong></td>\n            <td><span class=\"nc-blue_bg\">Sacrum</span></td>\n            <td>Sacro-prétibial + bi-trochantérien</td>\n          </tr>\n          <tr>\n            <td><strong>Transversale (épaule)</strong></td>\n            <td>Acromion</td>\n            <td><span><span class=\"nc-red nc-bold\">Césarienne requise</span></span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Rotation dans l’excavation</h4>\n\n      <p>Les <span class=\"nc-blue nc-bold\">rotations tendent à ramener l’</span><strong><span class=\"nc-blue nc-bold\">occiput en avant</span></strong> (OP) :</p>\n\n      <ul>\n        <li><strong>Variétés antérieures</strong> (<span class=\"nc-green_bg\">OIGA</span>, <span class=\"nc-pink nc-bold\">OIDA</span>) → rotation de <span>45°</span> vers l’avant (OP)</li>\n        <li><strong><span>97 %</span> des variétés postérieures</strong> (<span class=\"nc-pink nc-bold\">OIDP</span>, <span class=\"nc-green_bg\">OIGP</span>) → grande rotation de <span>135°</span> vers l’avant (OP)</li>\n        <li><strong><span>3 %</span> des variétés postérieures</strong> → rotation au plus court vers l’arrière en occipito-sacré (OS), <span>45°</span></li>\n      </ul>\n\n      <div class=\"callout callout-warn\">Repère de lecture : l’occiput oriente la variété de <span class=\"nc-blue nc-bold\">position</span> ; flexion, engagement <span class=\"nc-blue_bg\">puis</span> descente et rotation sont des phénomènes distincts. Les détails sont reliés au parcours interactif de l’accouchement.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : obj-8 (engagement) · obj-1 (mobile fœtal)</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Accouchement202017-RPC_HAS-CNGOF_Recommandations.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Accouchement normal, 2017</a></li></ul></details>","frequence":0},{"id":"31-11","rang":"B","rubrique":"Définition","titre":"Connaître les mécanismes périnéaux du dégagement de la tête fœtale","contenu":"<div class=\"notion-course\"><p>Le <span>dégagement</span> commence quand la tête du fœtus est à la partie basse de l’excavation et se termine avec la naissance. Il se déroule en 3 étapes périnéales successives.</p>\n\n      <h4>3 étapes du dégagement céphalique</h4>\n\n      <table>\n        <thead>\n          <tr><th>Étape</th><th>Phénomènes périnéaux</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1. <span class=\"nc-yellow_bg\">Distension du périnée postérieur</span></strong></td>\n            <td>\n              <ul>\n                <li><strong>Hyperflexion de la tête</strong> accentue la descente</li>\n                <li><strong>Rétropulsion du coccyx</strong> → agrandit le <span>diamètre</span> antéro-postérieur du DI de <span><span class=\"nc-pink nc-bold\">9 à 11 cm</span></span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>2. <span class=\"nc-yellow_bg\">Distension du périnée antérieur</span></strong></td>\n            <td>\n              <ul>\n                <li><strong>Noyau fibreux du périnée</strong> abordé de front, refoulé par la présentation qui s’en coiffe</li>\n                <li>Laminage et distension en tous sens</li>\n                <li><strong>Distance ano-vulvaire triple ou quadruple</strong></li>\n                <li>La vulve s’oriente directement « en avant »</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>3. <span class=\"nc-yellow_bg\">Dégagement de la présentation</span></strong></td>\n            <td>\n              <strong>Soit dégagement occipito-pubien (OP)</strong> — le plus fréquent (occiput s’appuie sur la SP)\n              <ol>\n                <li>Partie sous-occipitale se fixe sous la symphyse → point de rotation pour la <strong><span class=\"nc-blue_bg nc-bold\">déflexion</span></strong></li>\n                <li>Opérateur contrôle l’expulsion (main sur le sommet de la tête)</li>\n                <li><span class=\"nc-blue_bg nc-bold\">Déflexion</span> progressive : <strong><span class=\"nc-blue nc-bold\">bosses frontales</span> → <span class=\"nc-blue nc-bold\">yeux</span> → <span class=\"nc-blue nc-bold\">nez</span> → <span class=\"nc-blue nc-bold\">bouche</span> → <span class=\"nc-blue nc-bold\">menton</span></strong></li>\n                <li>Épisiotomie <strong>parfois nécessaire</strong>, <span>non systématique</span></li>\n              </ol>\n              <strong>Soit dégagement occipito-sacré (OS)</strong> — rare (occiput s’appuie contre le sacrum)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Asynclitisme et <span class=\"nc-brown_bg\">déformations plastiques</span></h4>\n\n      <ul>\n        <li><strong>Asynclitisme</strong> — inclinaison latérale facultative du sommet pour faciliter le passage</li>\n        <li><strong><span class=\"nc-brown_bg\">Déformations plastiques</span></strong> — modelage des os du crâne fœtal grâce aux sutures et fontanelles (bosse séro-sanguine possible)</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Rôle de l’opérateur.</strong> Contrôle de la sortie par une main sur le sommet pour <strong>éviter une expulsion brutale</strong> (déchirures périnéales). Épisiotomie discutée au cas par cas.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : obj-11 (techniques de poussée et dégagement) · obj-7 (<span>surveillance</span>)</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Accouchement202017-RPC_HAS-CNGOF_Recommandations.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Accouchement normal, 2017</a></li></ul></details>","frequence":0},{"id":"31-12","rang":"B","rubrique":"Prise en charge","titre":"Connaître les techniques de poussée et de dégagement","contenu":"<div class=\"notion-course\"><p>Les <span>techniques de poussée</span> sont à connaître pour accompagner efficacement la 2<sup>e</sup> étape du travail. La poussée doit être <strong>synchrone des CU</strong>, et les <span class=\"nc-brown_bg\">efforts expulsifs</span> ne doivent pas excéder <span>30 minutes</span>.</p>\n\n      <h4>Conditions préalables à l’expulsion</h4>\n\n      <ul>\n        <li><span>Surveillance</span> cardiotocographique <strong>maintenue en continu</strong></li>\n        <li><strong>Vessie <span class=\"nc-green_bg nc-bold\">vidée</span></strong> <span class=\"nc-green_bg\">préalablement</span></li>\n        <li><span class=\"nc-green_bg\">Installation en </span><strong><span class=\"nc-green_bg\">position</span> <span class=\"nc-green_bg nc-bold\">demi-assise</span></strong> si expulsion imminente</li>\n      </ul>\n\n      <h4>Physiologie de la poussée</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Réflexe de poussée.</strong> L’envie de pousser est déterminée par le <strong>contact de la <span class=\"nc-yellow_bg\">présentation</span> avec le plancher pelvi-périnéal</strong>. Les <span class=\"nc-yellow_bg\">efforts expulsifs </span><strong><span class=\"nc-yellow_bg\">volontaires</span></strong><span class=\"nc-yellow_bg\"> doivent être </span><strong><span class=\"nc-yellow_bg\">concomitants des CU</span></strong> pour assurer une bonne descente du mobile fœtal.\n      </div>\n\n      <h4>Technique en inspiration bloquée (Valsalva)</h4>\n\n      <ol>\n        <li><strong><span class=\"nc-blue_bg\">Inspirer</span></strong> → <span class=\"nc-blue_bg\">souffler</span> → <span class=\"nc-blue_bg\">inspirer</span></li>\n        <li><strong><span class=\"nc-blue_bg\">Bloquer la respiration</span></strong></li>\n        <li><strong><span class=\"nc-blue_bg\">Pousser vers le bas</span></strong><span class=\"nc-blue_bg\"> pendant toute la durée de la CU</span></li>\n        <li>Patiente <strong>se repose</strong> entre chaque CU (respiration ample et profonde)</li>\n        <li>Patiente <strong>arrête de pousser</strong> lorsque l’opérateur intervient (respiration lente et profonde) — <span>éviter une expulsion brusque qui risquerait d’entraîner des déchirures</span></li>\n      </ol>\n\n      <p><em>Technique de la <strong>poussée en expiration</strong> également possible (alternative à Valsalva).</em></p>\n\n      <h4>Dégagement du reste du corps</h4>\n\n      <table>\n        <thead>\n          <tr><th>Temps</th><th>Manœuvre</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1. Sortie de la tête — vérification du cordon</strong></td>\n            <td>\n              Vérifier l’<strong>absence de circulaire du cordon</strong> (anomalie : enroulement autour du cou).\n              <ul>\n                <li><strong>Circulaire lâche :</strong> faire glisser autour du thorax fœtal</li>\n                <li><strong>Circulaire serré :</strong> <span>couper entre 2 pinces Kocher</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>2. Rotation de restitution</strong></td>\n            <td>L’opérateur accentue la rotation spontanée — amène l’occiput fœtal à proximité de l’anus maternel (<span class=\"nc-blue_bg\">en OS</span>) → permet aux épaules de passer du <span>diamètre</span> oblique du DS au diamètre antéro-postérieur du DI</td>\n          </tr>\n          <tr>\n            <td><strong>3. Dégagement des épaules</strong></td>\n            <td>\n              Traction douce vers le bas dans l’axe ombilico-coccygien :\n              <ul>\n                <li>Épaule <strong><span class=\"nc-blue_bg nc-bold\">antérieure</span></strong> <span class=\"nc-blue_bg\">puis</span> <strong><span class=\"nc-blue_bg nc-bold\">postérieure</span></strong></li>\n                <li><span class=\"nc-blue nc-bold\">Passage du </span><strong><span><span class=\"nc-blue nc-bold\">diamètre</span></span><span class=\"nc-blue nc-bold\"> bi-acromial</span></strong></li>\n                <li><span>Temps d’extraction des épaules ne doit pas dépasser &lt; 40 secondes</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>4. Expulsion du siège</strong></td>\n            <td>Suit sans difficulté (<span>diamètre</span> bitrochantérien = <span>9 cm</span> seulement)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Après expulsion — clampage du cordon</h4>\n\n      <ul>\n        <li>Enfant posé <strong>sur le ventre de sa mère</strong>, tête en position déclive</li>\n        <li><strong>Clampage précoce</strong> — dès les premières secondes</li>\n        <li><span><strong>Clampage retardé (recommandé)</strong></span> — pendant <strong>&gt; 30 secondes jusqu’à <span <span=\"\">&gt;3</span> minutes</strong> avant le coupage → permet au bébé de bénéficier du transfert du sang du placenta (nutriments + cellules souches)</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : obj-10 (mécanismes périnéaux) · obj-7 (<span>surveillance</span>)</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Accouchement202017-RPC_HAS-CNGOF_Recommandations.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Accouchement normal, 2017</a></li></ul></details>","frequence":0},{"id":"31-13","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les différents temps de la délivrance","contenu":"<div class=\"notion-course\"><p>La <span><span class=\"nc-yellow_bg\">délivrance</span></span> = ensemble des phénomènes physiologiques aboutissant à l’expulsion du placenta et des membranes. Elle <strong>termine l’accouchement</strong> et se déroule en <strong>3 temps</strong>.</p>\n\n      <h4>3 temps de la délivrance</h4>\n\n      <table>\n        <thead>\n          <tr><th>Temps</th><th>Mécanisme</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1. Décollement placentaire</strong></td>\n            <td>\n              <ol>\n                <li><strong><span class=\"nc-yellow_bg\">Rétraction utérine</span></strong> dès la sortie de l’enfant → <span>réduction</span> de la surface d’insertion placentaire (villosités crampons tirent sur la muqueuse, amorçant le clivage et déchirant les sinus veineux)</li>\n                <li><strong>Intensification des CU</strong> après expulsion du fœtus → clivage (= cause essentielle ; fond utérin remonte au-dessus de l’ombilic)</li>\n                <li><strong>Hématome rétro-placentaire physiologique</strong> → complète la séparation</li>\n              </ol>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>2. Expulsion du placenta</strong></td>\n            <td>\n              Mécanisme principal : <strong>contractions utérines</strong>. Plus accessoirement : efforts expulsifs, poids du placenta, hématome inter-utéro-placentaire.<br>\n              <strong>Manœuvre douce :</strong>\n              <ul>\n                <li>1 main <span class=\"nc-blue_bg\">empaume le fond utérin pour abaisser le placenta fermement vers le bas</span></li>\n                <li>1 main maintient le cordon <strong>tendu <span class=\"nc-blue_bg nc-bold\">sans traction</span></strong></li>\n              </ul>\n              <span>⚠️ Ne pas tirer sur le cordon, ne pas exécuter de manœuvres hâtives</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>3. Hémostase</strong></td>\n            <td>\n              Assurée par :\n              <ul>\n                <li><strong><span class=\"nc-yellow_bg\">Thrombose des vaisseaux</span></strong> (facteurs de la coagulation)</li>\n                <li><strong><span class=\"nc-yellow_bg\">Rétraction utérine</span></strong> = phénomène des <span>ligatures vivantes</span> (<span class=\"nc-yellow_bg\">faisceaux musculaires de la couche plexiforme enserrent et obturent les vaisseaux</span>)</li>\n              </ul>\n              <em>Mécanisme efficace uniquement après évacuation totale de la cavité utérine.</em>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Reconnaissance clinique du décollement placentaire</h4>\n\n      <ul>\n        <li><strong><span class=\"nc-blue_bg\">Métrorragie</span></strong></li>\n        <li><strong><span class=\"nc-blue_bg\">Déroulement du cordon</span></strong><span class=\"nc-blue_bg\"> hors de la vulve</span> (pince témoin objective la descente)</li>\n        <li>Pression sus-pubienne / mobilisation utérine vers le haut <strong><span class=\"nc-yellow_bg\">ne fait pas remonter le cordon</span></strong> = <span>signe d’affirmation du décollement</span></li>\n        <li>Redescente du fond utérin après ascension momentanée</li>\n        <li><span>TV</span> susceptible d’affirmer la présence du placenta dans le vagin</li>\n      </ul>\n\n      <h4>Examen du placenta</h4>\n\n      <ul>\n        <li>Présentation à l’orifice vulvaire :\n          <ul>\n            <li><strong>Face fœtale</strong> — le plus souvent (mode <span><span class=\"nc-blue nc-bold\">Baudelocque</span></span>)</li>\n            <li><strong>Face maternelle ou bord</strong> — parfois (mode Duncan)</li>\n          </ul>\n        </li>\n        <li><strong>Sac membraneux :</strong> inspecté par transparence à la recherche d’une <span>zone dépolie/granuleuse où arrivent des vaisseaux</span> = <strong><span class=\"nc-red nc-bold\">cotylédon aberrant</span></strong> (<span class=\"nc-red nc-bold\">insertion sur les membranes à distance de la </span><span><span class=\"nc-red nc-bold\">masse</span></span><span class=\"nc-red nc-bold\"> placentaire</span>)</li>\n        <li><strong>Face fœtale :</strong> noter le lieu d’insertion du cordon, contrôler la présence de <span><span class=\"nc-pink nc-bold\">2 artères</span> + <span class=\"nc-pink nc-bold\">1 veine</span></span><span class=\"nc-pink nc-bold\"> funiculaires</span></li>\n        <li><strong>Face maternelle :</strong> débarrassée des caillots, cotylédons doivent se juxtaposer sans solution de continuité</li>\n      </ul>\n\n      <h4>Délivrance dirigée</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Délivrance dirigée — prévention HPP.</strong>\n        <ul>\n          <li><strong>Objectif :</strong> <span class=\"nc-green nc-bold\">prévention de l’hémorragie de la délivrance</span></li>\n          <li><strong>Principe :</strong> administration préventive d’<span>oxytocine IV 5–10 UI</span> (utérotonique)</li>\n          <li><strong>Quand ?</strong> idéalement <strong>au moment du dégagement des épaules</strong>, ou <span class=\"nc-pink nc-bold\">rapidement après la naissance</span></li>\n        </ul>\n      </div>\n\n      <h4><span>Délivrance artificielle</span> &amp; révision utérine</h4>\n\n      <table>\n        <thead>\n          <tr><th>Geste</th><th>Indication</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Délivrance artificielle</span></strong></td>\n            <td>Patiente <span>non délivrée après 30 minutes</span></td>\n          </tr>\n          <tr>\n            <td><strong><span>Révision utérine</span></strong></td>\n            <td>\n              <ul>\n                <li>Placenta incomplet (cotylédon manquant, absence du sac membraneux)</li>\n                <li><span><span class=\"nc-orange_bg\">Hémorragie du post-partum immédiat</span></span> (volume de sang perdu <span>≥ 500 cm³</span>)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Après l’hémostase — globe de sécurité.</strong>\n        <ul>\n          <li>Femme <strong><span class=\"nc-green nc-bold\">soulagée</span>, <span class=\"nc-green nc-bold\">détendue</span>, FC/PA normales</strong></li>\n          <li><span class=\"nc-yellow_bg\">Utérus</span> <span class=\"nc-yellow_bg nc-bold\">diminue de taille</span> → <span>masse</span> <strong><span class=\"nc-yellow_bg nc-bold\">dure</span> et <span class=\"nc-yellow_bg nc-bold\">arrondie</span></strong> en <span class=\"nc-yellow_bg nc-bold\">région sus-pubienne</span> = <span><span class=\"nc-yellow_bg\">globe de sécurité</span></span></li>\n        </ul>\n        Absence de globe de sécurité = <span>atonie utérine</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 24 — Complications de la <span>grossesse</span> · 34 — Suites de couches pathologiques · 332 — États de <span>choc</span> (HPP)</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Accouchement202017-RPC_HAS-CNGOF_Recommandations.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Accouchement normal, 2017</a></li></ul></details>","frequence":0},{"id":"31-14","rang":"A","rubrique":"Physiopathologie","titre":"Connaître les suites de couche normales","contenu":"<div class=\"notion-course\"><p>Les <span>suites de couches</span> = période d’<strong>environ <span><span class=\"nc-pink_bg\">6 semaines</span></span> (<span><span class=\"nc-pink_bg\">40 jours</span></span>)</strong> qui débute <strong><span><span class=\"nc-pink nc-bold\">2 h</span></span><span class=\"nc-pink nc-bold\"> après</span> l’accouchement</strong> et se termine par le <strong><span class=\"nc-green_bg\">retour de couches</span></strong><span class=\"nc-green_bg\"> (retour des menstruations)</span>.</p>\n\n      <h4>Éléments cliniques de <span>surveillance</span></h4>\n\n      <ul>\n        <li><strong>Signes généraux</strong> — pouls, PA, température, état général, douleur</li>\n        <li><strong>Seins</strong> — tension, douleur, crevasses</li>\n        <li><strong>Involution du globe utérin</strong> — hauteur et <span class=\"nc-blue nc-bold\">consistance</span> de l’<span class=\"nc-yellow_bg\">utérus</span></li>\n        <li><strong>Cicatrisation périnéale</strong></li>\n        <li><strong>Lochies</strong> (écoulement vaginal sanglant du post-partum) — abondance, aspect, odeur</li>\n        <li><strong>Membres inférieurs</strong> — recherche de signes de phlébite</li>\n        <li><strong>Appareil urinaire</strong> — signes fonctionnels, aspect des urines</li>\n        <li><strong>Si césarienne</strong> — cicatrice, douleur, reprise du transit, mictions et couleur des urines</li>\n      </ul>\n\n      <p><span>Hospitalisation</span> possible jusqu’au <span>12<sup>e</sup> jour</span> pour la sécurité sociale.</p>\n\n      <h4>Involution utérine</h4>\n\n      <table>\n        <thead>\n          <tr><th>Élément</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Mécanisme</strong></td>\n            <td><span class=\"nc-yellow_bg\">Diminution du volume</span> + <span class=\"nc-yellow_bg\">réintégration de l’utérus dans la cavité pelvienne</span> (sous l’influence de <strong>CU infracliniques</strong>, <span><span class=\"nc-blue nc-bold\">douloureuses chez la multipare</span></span> = « <span>tranchées</span> »)</td>\n          </tr>\n          <tr>\n            <td><strong>Facteurs favorisants</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-brown_bg\">Prescription d’</span><span><span class=\"nc-brown_bg\">ocytociques</span></span> (favorisent les CU et donc l’involution)</li>\n                <li><span>Allaitement</span> maternel (la succion du nouveau-né stimule la libération d’ocytocine)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>Évolution</span></strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-yellow_bg\">Utérus</span> gros/globuleux pendant <span>15 jours</span> → retrouve sa taille normale en <span>2–3 mois</span></li>\n                <li>Reconstitution du col utérin :\n                  <ul>\n                    <li>Col prend de la longueur et de la consistance</li>\n                    <li>Fermeture de l’orifice interne : vers le <span><span class=\"nc-pink nc-bold\">10</span><sup><span class=\"nc-pink nc-bold\">e</span></sup><span class=\"nc-pink nc-bold\"> jour</span></span></li>\n                    <li>Fermeture de l’orifice externe : vers le <span><span class=\"nc-pink nc-bold\">15–20</span><sup><span class=\"nc-pink nc-bold\">e</span></sup><span class=\"nc-pink nc-bold\"> jour</span></span></li>\n                    <li>Disparition du segment inférieur : <span class=\"nc-pink nc-bold\">en quelques jours</span></li>\n                  </ul>\n                </li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Lochies</h4>\n\n      <ul>\n        <li><strong><span class=\"nc-pink nc-bold\">4 premiers jours</span> :</strong> écoulement sérosanguinolent/sanglant physiologique</li>\n        <li><strong><span class=\"nc-green_bg\">Éclaircissement progressif</span> :</strong> lochies <strong>totalement claires vers J10</strong></li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Globe de sécurité.</strong> L’utérus doit conserver le classique <span>globe de sécurité</span> (utérus rétracté et tonique) lors du séjour en maternité.\n        <ul>\n          <li>Contrôle <strong>journalier</strong> de l’involution utérine</li>\n          <li>Pathologies où l’utérus est mal involué : <span><span class=\"nc-orange nc-bold\">atonie utérine</span></span>, <span><span class=\"nc-orange nc-bold\">endométrite du post-partum</span></span></li>\n        </ul>\n      </div>\n\n      <h4>Retour de couches &amp; ovulation</h4>\n\n      <table>\n        <thead>\n          <tr><th>Élément</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Reconstitution endomètre (3 phases)</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-yellow_bg\">Régression</span> : <span>4–5 jours</span> (dégénérescence de la caduque)</li>\n                <li><span class=\"nc-yellow_bg\">Cicatrisation</span> : jusqu’au 25<sup>e</sup> jour</li>\n                <li><span class=\"nc-yellow_bg\">Prolifération</span> : 25–45<sup>e</sup> jour</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Sans <span>allaitement</span></strong></td>\n            <td>Retour de couches vers le <span>45<sup>e</sup> jour</span> post-partum (<span>6–12 semaines</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Avec <span>allaitement</span> maternel</strong></td>\n            <td>Retour en <span>4–6 mois</span> (≈ <span><span class=\"nc-pink_bg\">40 jours</span></span> après la fin de l’<span>allaitement</span>) — endomètre garde un aspect régressif de repos</td>\n          </tr>\n          <tr>\n            <td><strong>Petit retour de couches</strong></td>\n            <td>Hémorragie de faible abondance vers le <strong>20<sup>e</sup> jour</strong> pendant <span>2–3 jours</span></td>\n          </tr>\n          <tr>\n            <td><strong>Ovulation</strong></td>\n            <td>\n              <span>1<sup>er</sup> cycle peut être ovulatoire dans 5–10 % des cas</span><br>\n              <strong>L’<span>allaitement</span> maternel n’est pas une contraception garantie</strong> ⚠️\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Sécrétion lactée</h4>\n\n      <table>\n        <thead>\n          <tr><th>Hormone</th><th>Rôle</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span><span class=\"nc-pink nc-bold\">Prolactine</span></span></strong></td>\n            <td>Conditionne la <strong>synthèse + stockage/sécrétion</strong> du lait par les lactocytes (galactopoïèse)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-pink nc-bold\">Ocytocine</span></strong></td>\n            <td>Favorise l’<strong><span class=\"nc-green_bg\">éjection du lait</span></strong> en stimulant la contraction des cellules myo-épithéliales autour des lactocytes</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Montée laiteuse</strong> — survient au <span>2–3<sup>e</sup> jour</span> du post-partum (= 2<sup>e</sup> phase de la lactogenèse) :\n        <ul>\n          <li>Seins gonflent, tendus et sensibles, <strong><span class=\"nc-blue_bg\">fébricule</span> transitoire possible à <span>38 °C</span></strong></li>\n          <li>Liée à l’asynchronisme entre lactogenèse et mécanismes d’<span class=\"nc-green_bg\">éjection du lait</span></li>\n          <li>Normalisation par tétées fréquentes et efficaces</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : obj-14 (PEC post-partum immédiat) · obj-15 (contraception) · 34 — Suites de couches pathologiques · 69 — Troubles psychiques de la <span>grossesse</span> et du post-partum</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Accouchement202017-RPC_HAS-CNGOF_Recommandations.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Accouchement normal, 2017</a></li></ul></details>","frequence":0},{"id":"31-15","rang":"A","rubrique":"Prise en charge","titre":"Savoir prendre en charge une accouchée dans le post-partum immédiat","contenu":"<div class=\"notion-course\"><p>La prise en charge du <span>post-partum immédiat</span> vise 5 objectifs structurants pendant le séjour en maternité.</p>\n\n      <h4>5 objectifs du séjour en maternité</h4>\n\n      <ul>\n        <li><strong>Favoriser et contrôler</strong> la bonne involution de l’utérus + s’assurer de l’absence d’hémorragie</li>\n        <li><strong>Contrôler l’<span>allaitement</span></strong></li>\n        <li><strong>Prévenir et dépister</strong> les infections locales et générales + les accidents thromboemboliques</li>\n        <li><strong>Soins du périnée</strong> — toilettes fréquentes, éviter la macération, information sur la rééducation pelvi-périnéale</li>\n        <li><strong>Information médicale + actions de prévention</strong></li>\n      </ul>\n\n      <h4><span>Allaitement</span> maternel — bonnes pratiques</h4>\n\n      <table>\n        <thead>\n          <tr><th>Item</th><th>Recommandation</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1<sup>re</sup> tétée</strong></td>\n            <td><span class=\"nc-green_bg\">Mise au sein </span><strong><span class=\"nc-green_bg\">immédiate</span></strong>, <span class=\"nc-green_bg\">si possible en salle de travail</span> (sans précipitation, <span><span class=\"nc-pink nc-bold\">&lt; 30 min</span></span> après la naissance) — le colostrum est très riche en Ig, et le réflexe de succion est à son maximum</td>\n          </tr>\n          <tr>\n            <td><strong>Installation</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-blue_bg\">Mère assise ou couchée</span>, <span class=\"nc-blue_bg\">donner les </span><strong><span class=\"nc-blue_bg\">2 seins à chaque tétée</span></strong> (alterner = diminue les complications)</li>\n                <li><span class=\"nc-yellow_bg\">Bouche du nouveau-né doit prendre </span><strong><span class=\"nc-yellow_bg\">largement l’aréole</span></strong> (<span class=\"nc-red nc-bold\">pas seulement le mamelon</span>)</li>\n                <li><span class=\"nc-blue nc-bold\">Menton</span> et <span class=\"nc-blue nc-bold\">nez</span> contre le sein, tête légèrement inclinée en arrière</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Horaires</strong></td>\n            <td>\n              <span>Allaitement</span> <strong>souple à la demande</strong>. Fréquence moyenne : <span>1 tétée toutes les 2–3 h au début</span>, puis espacement progressif guidé par le nouveau-né.\n              <ul>\n                <li>Signes : regard/comportement (mouvements <span class=\"nc-blue nc-bold\">yeux</span>, lèvres, tête, main à la <span class=\"nc-blue nc-bold\">bouche</span>)</li>\n                <li><span class=\"nc-red_bg\">Ne pas attendre l’agitation ou les pleurs</span></li>\n                <li><span class=\"nc-red_bg\">Ne pas juger seulement sur la courbe de poids</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Durée</strong></td>\n            <td>Variable selon l’enfant — très courte (efficace, actif) à plus longue (prématurés, lent, tétouille)</td>\n          </tr>\n          <tr>\n            <td><strong>Signes d’<span>allaitement</span> efficace</strong></td>\n            <td>\n              <ul>\n                <li><strong>Tétées</strong> —<span> 8–12<span class=\"nc-yellow_bg\">/jour</span></span> de façon efficace (<span class=\"nc-green_bg\">y compris la nuit pendant les 1</span><sup><span class=\"nc-green_bg\">ers</span></sup><span class=\"nc-green_bg\"> mois</span>)</li>\n                <li><strong>Selles</strong> — &gt;<span> 3<span class=\"nc-yellow_bg\">/jour</span></span> <span class=\"nc-yellow_bg nc-bold\">molles</span>, <span class=\"nc-yellow_bg nc-bold\">grumeleuses</span>, <span class=\"nc-yellow_bg nc-bold\">jaunes</span></li>\n                <li><strong>Urines</strong> — <span class=\"nc-yellow_bg\">5–6 couches mouillées et lourdes/jour</span> (diurèse satisfaisante)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Conseils à favoriser ✅</h4>\n\n      <ul>\n        <li>Laisser l’enfant avec sa mère <strong><span>24 h</span> sur 24</strong></li>\n        <li><span class=\"nc-blue_bg\">Lavage quotidien des seins à l’eau et au savon</span></li>\n        <li>Protection des mamelons avec compresse sèche (éviter macération)</li>\n        <li>Encourager les associations de soutien à l’<span>allaitement</span> maternel</li>\n        <li>Boissons abondantes, alimentation variée et riche en protéines et calcium</li>\n      </ul>\n\n      <h4>À éviter ❌</h4>\n\n      <ul>\n        <li><strong>Proscription du <span>tabac</span>, <span>alcool</span>, excitants</strong> (café, thé)</li>\n        <li><strong>Pas de tétine artificielle ou sucette</strong> chez l’enfant allaité</li>\n        <li>Éviter les crèmes cosmétiques sur les seins ; <strong>pas d’antisepsie nécessaire</strong></li>\n        <li>Aucun médicament ou régime alimentaire censé augmenter la sécrétion lactée</li>\n        <li>Production de lait diminue si ajout de biberons (moins de stimulation)</li>\n      </ul>\n\n      <h4>Prévention de la maladie thromboembolique veineuse (MTEV)</h4>\n\n      <table>\n        <thead>\n          <tr><th>Niveau de risque</th><th>Facteurs</th><th>Prophylaxie</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Risque majeur</strong></td>\n            <td>\n              <ul>\n                <li>ATCD de <strong><span class=\"nc-red nc-bold\">MTEV multiples</span></strong></li>\n                <li><strong><span class=\"nc-red nc-bold\">Thrombophilie</span></strong><span class=\"nc-red nc-bold\"> traitée au long cours</span> par <span>anticoagulant</span></li>\n              </ul>\n            </td>\n            <td><span class=\"nc-green_bg\">Bas de contention</span> + <strong><span><span class=\"nc-pink nc-bold\">AVK</span></span></strong> pendant <span><span class=\"nc-pink nc-bold\">≥ 3 mois</span></span></td>\n          </tr>\n          <tr>\n            <td><strong>Risque élevé</strong></td>\n            <td>\n              <ul>\n                <li>ATCD MTEV sans FR retrouvé</li>\n                <li>ATCD MTEV en contexte de <span>grossesse</span> ou de traitement œstrogénique</li>\n                <li>ATCD MTEV + facteur <span>biologique</span> (déficit AT, <span class=\"nc-red\">SAPL</span>, mutation <span class=\"nc-red\">20210A</span> homozygote, <span>FV <span class=\"nc-red\">Leiden</span></span> homozygote, anomalies hétérozygotes combinées)</li>\n              </ul>\n            </td>\n            <td><span class=\"nc-green_bg\">Bas de contention</span> + <strong><span><span class=\"nc-pink nc-bold\">HBPM à dose prophylactique forte</span></span></strong> (<span>énoxaparine</span> 4 <span>000 UI</span>/j ou <span>daltéparine</span> 5 <span>000 UI</span>/j) pendant <span>6–8 semaines</span></td>\n          </tr>\n          <tr>\n            <td><strong>Risque modéré</strong></td>\n            <td>\n              <ul>\n                <li>ATCD MTEV avec facteur déclenchant temporaire</li>\n                <li>ATCD MTEV + autre facteur <span>biologique</span></li>\n                <li>Facteur <span>biologique</span> asymptomatique dépisté dans une MTEV familiale</li>\n                <li><strong><span class=\"nc-pink_bg\">Césarienne en </span><span><span class=\"nc-pink_bg\">urgence</span></span></strong></li>\n                <li>Césarienne + <span>chirurgie</span> pelvienne majeure associée</li>\n                <li>Présence de <span>≥ 3</span> FR faibles</li>\n              </ul>\n            </td>\n            <td><span class=\"nc-green_bg\">Bas de contention</span> + <strong><span><span class=\"nc-pink nc-bold\">HBPM à dose prophylactique forte</span></span></strong> pendant <span>6–8 semaines</span> (dose et durée modulables)</td>\n          </tr>\n          <tr>\n            <td><strong>Risque faible</strong></td>\n            <td>\n              Si &lt; 3 FR suivants : <span class=\"nc-pink_bg\">âge &gt;</span><span><span class=\"nc-pink_bg\"> 35 ans</span></span>, <span><span class=\"nc-pink_bg\">obésité</span></span> (IMC &gt; 30 ou poids &gt;<span> 80 kg</span>), <span class=\"nc-pink_bg\">varices</span>, <span><span class=\"nc-pink_bg\">HTA</span></span>, <span class=\"nc-blue_bg\">césarienne</span>, <span class=\"nc-blue_bg\">multiparité &gt; 4</span>, <span><span class=\"nc-blue_bg\">prééclampsie</span></span>, <span class=\"nc-blue_bg\">alitement strict prolongé</span>, HPP, <span>syndrome néphrotique</span>, <span>MICI</span> en poussée, infection systémique\n            </td>\n            <td><span class=\"nc-green_bg\">Bas de contention</span> seuls — <span>pas d’anticoagulant</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : obj-13 (suites de couches) · obj-15 (contraception PP) · 34 — Suites de couches pathologiques · 226 — <span>TVP</span> / EP · 69 — Troubles psychiques de la <span>grossesse</span> et du PP</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Accouchement202017-RPC_HAS-CNGOF_Recommandations.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Accouchement normal, 2017</a></li></ul></details>","frequence":0},{"id":"31-16","rang":"B","rubrique":"Prise en charge","titre":"Savoir prescrire une contraception du post partum","contenu":"<div class=\"notion-course\"><p>La <span>contraception du post-partum</span> est <strong>provisoire</strong> et devra être rediscutée à la visite postnatale. Sa précocité de mise en place est cruciale : la reprise de la fertilité est précoce (mais pas avant <span>25 jours</span>).</p>\n\n      <h4>Généralités</h4>\n\n      <table>\n        <thead>\n          <tr><th>Élément</th><th>Donnée clé</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Reprise des rapports</strong></td>\n            <td>En moyenne <span>5 semaines</span> après l’accouchement — à <span>1 mois</span>, ≈ <span>60 %</span> des couples ont eu <span>≥ 1</span> rapport</td>\n          </tr>\n          <tr>\n            <td><strong>IVG post-PP</strong></td>\n            <td><span>5,5 % des IVG en France</span> surviennent dans les <span>6 mois</span> après un accouchement (≈ 11 000 femmes/an)</td>\n          </tr>\n          <tr>\n            <td><strong>Reprise de la fertilité</strong></td>\n            <td>Précoce, mais <strong>pas avant <span>25 jours</span></strong> → <span>débuter la contraception vers le 21<sup>e</sup> jour</span></td>\n          </tr>\n          <tr>\n            <td><strong>Visite postnatale</strong></td>\n            <td><span>30 %</span> des femmes n’ont pas repris ou ont abandonné leur contraception → méthode prescrite souvent non adaptée à toutes</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Quand reprendre l’activité sexuelle ?</h4>\n\n      <p>Dès que le <strong>périnée est confortable et guéri</strong> et que le <strong>sang rouge clair a disparu</strong> : <span><span class=\"nc-pink nc-bold\">2–3 semaines</span></span>.</p>\n\n      <h4>Méthodes contraceptives — post-partum</h4>\n\n      <table>\n        <thead>\n          <tr><th>Méthode</th><th>Modalités en post-partum</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Méthodes barrières</strong> ✅</td>\n            <td>\n              <span class=\"nc-blue_bg\">Préservatifs</span>, <span class=\"nc-blue_bg\">spermicides (crèmes, ovules, éponges)</span>.<br>\n              <span><span class=\"nc-red nc-bold\">Diaphragme plus difficile à utiliser en post-partum</span> ❌</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>DIU (stérilet)</strong></td>\n            <td>\n              <strong>Avantages :</strong>\n              <ul>\n                <li><span class=\"nc-green_bg\">Pose sans danger</span> (risque infection/perforation non augmenté)</li>\n                <li>Méthode idéale chez la femme qui allaite (aucun effet sur la qualité/composition du lait)</li>\n              </ul>\n              <strong>Inconvénient principal :</strong>\n              <ul>\n                <li><span><span class=\"nc-red nc-bold\">Taux élevé d’expulsion</span></span> à cause des CU et de la dilatation cervicale (<span>12–40 %</span> expulsés à <span>6 mois</span>)</li>\n                <li><strong>Prévention :</strong> <span class=\"nc-pink nc-bold\">pose idéalement après </span><span><span class=\"nc-pink nc-bold\">≥ 3 mois</span></span> (après retour de couches ou en fin d’involution utérine)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Œstro-progestatifs (COP)</strong> ❌</td>\n            <td>\n              <strong>Ne pas prescrire avant le 3<sup>e</sup> mois</strong> après un accouchement :\n              <ul>\n                <li><span><span class=\"nc-red nc-bold\">Risque thrombotique majoré</span></span> (pendant <span>grossesse</span> + post-partum pendant <span>≥ 6–9 semaines</span>)</li>\n                <li><span><span class=\"nc-red nc-bold\">Risque d’ablactation</span></span><span class=\"nc-red nc-bold\"> avant </span><span><span class=\"nc-red nc-bold\">6 semaines</span></span> chez la femme allaitante</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Micro-progestatifs</strong> ✅</td>\n            <td>\n              <ul>\n                <li><strong>Quand ?</strong> en continu <strong><span class=\"nc-green_bg nc-bold\">à partir du 21</span><sup><span class=\"nc-green_bg nc-bold\">e</span></sup><span class=\"nc-green_bg nc-bold\"> jour</span></strong> (voie orale ou implant)</li>\n                <li><strong>Inconvénients :</strong> <span class=\"nc-red nc-bold\">métrorragies</span>, <span class=\"nc-red nc-bold\">spottings</span> (taches de sang en dehors des règles)</li>\n                <li><strong>Avantages :</strong> pas de répercussions métaboliques/systémiques, effet sur l’<span>allaitement</span> et l’enfant négligeable</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Stérilisation</strong></td>\n            <td>\n              <ul>\n                <li><strong>Quand ?</strong> au moment d’une césarienne, ou dans les <span>24–48 h</span> après un accouchement non compliqué</li>\n                <li><strong>Vigilance :</strong> <span>stérilisation s’accompagne plus souvent de regrets en post-partum immédiat</span></li>\n                <li><strong>Avantage :</strong> n’allonge pas l’<span>hospitalisation</span>. Taux d’échec <span>0,5–1 %</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Méthode MAMA (<span>allaitement</span> maternel et aménorrhée)</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>MAMA — méthode naturelle pendant les 6 premiers mois</strong>\n        <ul>\n          <li><strong>Principe :</strong> <span><span class=\"nc-blue nc-bold\">allaitement</span></span><span class=\"nc-blue nc-bold\"> </span><strong><span class=\"nc-blue nc-bold\">exclusif à la demande</span></strong>, <span class=\"nc-blue nc-bold\">jour et nuit</span> + persistance d’une aménorrhée</li>\n          <li><strong>Efficacité :</strong> indice de Pearl à <span>7 %</span> (taux <span>grossesse</span> à<span> 1 an</span>)</li>\n          <li><strong>Conseil :</strong> <span class=\"nc-pink_bg\">associer une contraception locale (</span><span class=\"nc-pink_bg nc-bold\">préservatifs</span>, <span class=\"nc-pink_bg nc-bold\">spermicides</span><span class=\"nc-pink_bg\">) pour potentialiser l’efficacité</span></li>\n          <li><strong>Précaution :</strong> <span>allaitement doit être exclusif</span>, sinon une méthode fiable est nécessaire</li>\n        </ul>\n      </div>\n\n      <h4>Contraception et <span>allaitement</span> — résumé</h4>\n\n      <table>\n        <thead>\n          <tr><th>Méthode</th><th>Compatibilité avec l’allaitement</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Œstro-progestatifs</strong></td><td><span>❌ Pas recommandés</span> — risque thromboembolique + diminution de la production lactée</td></tr>\n          <tr><td><strong>Micro-progestatifs, <span class=\"nc-green_bg\">implants progestatifs</span></strong></td><td>✅ Utilisables sans inconvénient</td></tr>\n          <tr><td><strong>DIU</strong></td><td>✅ Sans danger</td></tr>\n          <tr><td><strong><span class=\"nc-blue_bg\">Préservatifs</span>, <span class=\"nc-blue_bg\">spermicides</span></strong></td><td>✅ Utilisables (efficacité limitée, contraignants)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Risque d’ovulation au cours de l’<span>allaitement</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Situation</th><th>6 sem.</th><th>9 sem.</th><th>12 sem.</th><th>18 sem.</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span>Allaitement</span> en cours</strong></td><td><span>0 %</span></td><td><span>1 %</span></td><td><span>17 %</span></td><td><span>36 %</span></td></tr>\n          <tr><td><strong><span>Allaitement</span> &lt; <span>6 semaines</span></strong></td><td><span>12 %</span></td><td><span>79 %</span></td><td><span>99 %</span></td><td>—</td></tr>\n          <tr><td><strong><span>Allaitement</span> &lt; <span>4 semaines</span></strong></td><td><span>14 %</span></td><td><span>89 %</span></td><td><span>99,5 %</span></td><td>—</td></tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 36 — Contraception · obj-13 (suites de couches) · obj-14 (PEC post-partum) · 34 — Suites de couches pathologiques</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Accouchement202017-RPC_HAS-CNGOF_Recommandations.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Accouchement normal, 2017</a></li></ul></details>","frequence":2}],"astuces":[],"strategie":{"hospit":"<p><strong>Outil :</strong> <span class=\"kw-def\">partogramme</span> — <span class=\"kw-def\">surveillance</span> clinique + paraclinique <span class=\"kw-chiffre\">au minimum toutes les heures</span> pendant le travail.</p><ul><li>Toucher vaginal aseptique toutes les <span class=\"kw-chiffre\">30 min – 1 h</span> : présentation et variété, état de la poche des eaux, <span class=\"kw-def\">score de Bishop</span> (dilatation, effacement, consistance, position du col, hauteur de la présentation)</li><li>Palpation abdominale (présentation longitudinale / transversale) ; <span class=\"kw-clinique\">hauteur utérine</span> ≈ <span class=\"kw-chiffre\">33 cm</span> hors contraction</li><li><span class=\"kw-imagerie\">Cardiotocographe</span> : RCF en <span class=\"kw-chiffre\">surveillance continue</span> pendant les 2 premiers stades + tocographie (CU : hypo/hypercinésie, hypo/hypertonie)</li><li><span class=\"kw-imagerie\">Échographie</span> en salle si besoin : présentation, quantité de LA, insertion placentaire</li><li><span class=\"kw-ttt\">Antibioprophylaxie anti-SGB</span> chez les femmes à risque (pénicilline G, <span class=\"kw-ttt\">amoxicilline</span>, ampicilline, céfazoline)</li><li><span class=\"kw-alerte\">Hospitalisation</span> possible jusqu’au <span class=\"kw-chiffre\">12ᵉ jour</span> (prise en charge sécurité sociale)</li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Liquide amniotique méconial</span> (vert ± sombre) → signe d’<span class=\"kw-alerte\">état fœtal non rassurant</span> (toute émission de méconium avant la naissance traduit une pathologie)</li><li>LA <span class=\"kw-clinique\">épais ou teinté</span> → évoquer une <span class=\"kw-etio\">chorioamniotite</span></li><li><span class=\"kw-alerte\">Rupture prématurée des membranes</span> (avant tout travail) → risque d’<span class=\"kw-etio\">infection</span> + <span class=\"kw-alerte\">procidence du cordon</span> → <span class=\"kw-ttt\">hospitalisation immédiate</span></li><li>Après <span class=\"kw-alerte\">rupture</span> artificielle des membranes : <span class=\"kw-ttt\">réexaminer</span> pour vérifier l’absence de <span class=\"kw-alerte\">procidence du cordon</span></li><li>Anomalies des CU : <span class=\"kw-alerte\">hypercinésie / hypertonie</span> (risque d’hypoxie fœtale par baisse des échanges utéro-placentaires)</li><li><span class=\"kw-alerte\">Circulaire du cordon serré</span> à la sortie de la tête → section entre 2 pinces Kocher</li><li>Stagnation de la dilatation : <span class=\"kw-chiffre\">&lt; 1 cm/4 h</span> (<span class=\"kw-chiffre\">5–7 cm</span>) ou <span class=\"kw-chiffre\">&lt; 1 cm/2 h</span> (<span class=\"kw-chiffre\">7 cm</span> → complète) → <span class=\"kw-alerte\">dystocie dynamique</span></li><li>Post-partum : <span class=\"kw-alerte\">utérus mal involué</span> / perte du « globe de sécurité » → <span class=\"kw-etio\">atonie utérine</span>, <span class=\"kw-etio\">endométrite du post-partum</span>, <span class=\"kw-alerte\">HPP</span> (≥ <span class=\"kw-chiffre\">500 mL</span>)</li></ul>","principes":"<p><strong>Moteur :</strong> les <span class=\"kw-def\">contractions utérines</span> assurent la dilatation du col et la descente du fœtus dans la filière pelvienne ; <span class=\"kw-ttt\">analgésie péridurale</span> possible dès le début du travail.</p><ul><li><strong>1ᵉʳ <span class=\"kw-def\">stade</span> (dilatation)</strong> : phase de latence (→<span class=\"kw-chiffre\"> 5–6 cm</span>) puis phase active jusqu’à dilatation complète (<span class=\"kw-chiffre\">10 cm</span>)</li><li><strong><span class=\"kw-alerte\">Rupture</span> artificielle des membranes</strong> : possible si dilatation <span class=\"kw-chiffre\">&gt; 6 cm</span> et présentation engagée (aide la marche du travail)</li><li><strong>2ᵉ <span class=\"kw-def\">stade</span> (expulsion)</strong> : efforts expulsifs concomitants des CU, <span class=\"kw-chiffre\">≤ 30 min</span> ; vérifier l’absence de circulaire du cordon à la sortie de la tête</li><li><strong>3ᵉ <span class=\"kw-def\">stade</span> (délivrance dirigée)</strong> : <span class=\"kw-ttt\">ocytocine 5–10 UI IV</span> au dégagement des épaules → prévention de l’hémorragie de la délivrance ; examen systématique du placenta</li><li><strong>Hémostase</strong> : rétraction utérine = phénomène des <span class=\"kw-def\">ligatures vivantes</span> (efficace seulement après vacuité utérine totale)</li><li><strong>Prévention MTEV</strong> : bas de contention ± <span class=\"kw-ttt\">HBPM prophylactique</span> (6–8 sem) ou <span class=\"kw-ttt\">AVK ≥ 3 mois</span> selon le niveau de risque</li><li><strong>Allo-immunisation Rh</strong> : test de Kleihauer puis <span class=\"kw-ttt\">Ig anti-D &lt; 72 h</span> si mère Rh− et enfant Rh+</li></ul>","suivi":"<p><strong>Durée :</strong> suites de couches ≈ <span class=\"kw-chiffre\">6 semaines (40 j)</span>, de la <span class=\"kw-chiffre\">2ᵉ heure</span> post-accouchement jusqu’au retour de couches.</p><ul><li><strong><span class=\"kw-def\">Surveillance</span> clinique quotidienne</strong> : constantes, seins (tension, crevasses), involution du globe utérin, cicatrisation périnéale, <span class=\"kw-clinique\">lochies</span> (abondance, aspect, odeur), membres inférieurs (phlébite), appareil urinaire ; cicatrice si césarienne</li><li><strong>Involution utérine</strong> : favorisée par les <span class=\"kw-ttt\">ocytociques</span> et l’<span class=\"kw-clinique\">allaitement</span> ; tranchées douloureuses chez la <span class=\"kw-clinique\">multipare</span></li><li><strong>Lochies</strong> : sanglantes <span class=\"kw-chiffre\">J1–J4</span> → claires vers <span class=\"kw-chiffre\">J10</span> ; « petit retour de couches » possible vers <span class=\"kw-chiffre\">J20</span></li><li><strong>Retour de couches</strong> : vers <span class=\"kw-chiffre\">J45</span> (6 sem) sans <span class=\"kw-ci\">allaitement</span> ; <span class=\"kw-chiffre\">4–6 mois</span> si allaitement maternel</li><li><strong>Objectifs du séjour</strong> : contrôler l’involution + l’absence d’hémorragie, contrôler l’<span class=\"kw-ci\">allaitement</span>, dépister infections et MTEV, soins du périnée, information (rééducation pelvi-périnéale, contraception)</li></ul>"},"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Travail physiologique à bas risque ?","detail":"<ul><li>Présentation, terme, constantes et rythme fœtal ; consentement.</li></ul>","branches":[{"label":"Anomalie / risque","to":"obst"},{"label":"Oui","to":"travail"}]},{"id":"travail","kind":"decision","label":"Suivre la progression et le bien-être","detail":"<ul><li>Contractions, col, douleur, rythme fœtal ; mobilité et analgésie choisies.</li></ul>","branches":[{"label":"Progression / dilatation complète","to":"expulsion"},{"label":"Anomalie","to":"obst"}]},{"id":"expulsion","kind":"decision","label":"Engagement, rotation et dégagement","detail":"<ul><li>Accompagnement des efforts ; pas de gestes systématiques non indiqués.</li></ul>","branches":[{"label":"Naissance","to":"delivrance"},{"label":"Difficulté / anomalie","to":"obst"}]},{"id":"delivrance","kind":"decision","label":"Délivrance et prévention de l’HPP","detail":"<ul><li>Placenta complet, tonus et quantification des pertes.</li></ul>","branches":[{"label":"Saignement anormal","to":"hpp"},{"label":"Normal","to":"postpartum"}]},{"id":"postpartum","kind":"finish","label":"Surveillance mère–enfant","detail":"<ul><li>PA/pouls, globe utérin, pertes, douleur, lien et alimentation ; contraception.</li></ul>","branches":[]},{"id":"hpp","kind":"urgent","label":"Déclencher le parcours HPP","detail":"<ul><li>Réanimation et traitement de la cause en parallèle.</li></ul>","branches":[]},{"id":"obst","kind":"urgent","label":"Réévaluation obstétricale","detail":"<ul><li>Adapter surveillance et intervention à la cause, sans poursuivre aveuglément le parcours physiologique.</li></ul>","branches":[]}]},"cards":[{"i":"b0233a143914","n":31,"o":"31-1","u":"Définition","t":"Connaître les différents éléments du bassin maternel","q":"Que retenir concernant les différents éléments du bassin maternel ?","a":"<div class=\"notion-course\"><p>Le <span>bassin maternel</span> est la structure osseuse qui constitue la <strong>filière pelvienne obstétricale</strong>. Sa connaissance anatomique conditionne la compréhension de l’engagement, de la descente et du dégagement du mobile fœtal.</p>\n\n      <h4>Ceinture pelvienne — anneau ostéo-articulaire</h4>\n\n      <ul>\n        <li><strong>4 os :</strong> <span class=\"nc-blue_bg\">2 os coxaux</span> + <span class=\"nc-blue_bg\">sacrum</span> + <span class=\"nc-blue_bg\">coccyx</span></li>\n        <li><strong>4 articulations</strong> (très peu mobiles) : <span class=\"nc-blue_bg\">2 articulations sacro-iliaques</span> + <span class=\"nc-blue_bg\">symphyse pubienne</span> + <span class=\"nc-blue_bg\">articulation sacro-coccygienne</span></li>\n      </ul>\n\n      <h4>Filière pelvienne — 3 étages</h4>\n\n      <table>\n        <thead>\n          <tr><th>Étage</th><th>Repères &amp; diamètres</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Détroit supérieur (DS)</strong><br><em>= <span class=\"nc-blue nc-bold\">cylindre d’engagement</span> de Demelin</em></td>\n            <td>\n              <strong>Limites :</strong>\n              <ul>\n                <li>Avant : <span class=\"nc-blue_bg\">bord supérieur de la symphyse pubienne</span></li>\n                <li>Arrière : <span><span class=\"nc-blue_bg\">promontoire</span></span> (disque vertébral L5–S1, <span>9 cm</span> au-dessus de SP)</li>\n                <li>Latéralement : <span class=\"nc-blue_bg\">lignes innominées</span></li>\n              </ul>\n              <strong>Forme :</strong> cœur de carte à jouer (rétréci en sagittal par la saillie du promontoire)<br>\n              <strong>Diamètres :</strong>\n              <ul>\n                <li>Promonto-rétropubien : <span><span class=\"nc-pink nc-bold\">10,5 cm</span></span></li>\n                <li>Transverse médian : <span><span class=\"nc-pink nc-bold\">12,5 cm</span></span></li>\n              </ul>\n              <strong>Axe :</strong> oblique en arrière et en bas, vise l’interligne sacro-coccygien\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Excavation pelvienne</strong><br><em>= canal pelvien / petit bassin</em></td>\n            <td>\n              <strong>Limites :</strong>\n              <ul>\n                <li>Hautes/basses : entre <span class=\"nc-blue nc-bold\">cylindre d’engagement</span> et détroit inférieur</li>\n                <li>Avant/arrière : <span class=\"nc-blue nc-bold\">symphyse pubienne</span> ↔ <span class=\"nc-blue nc-bold\">face antérieure du sacrum</span></li>\n                <li>Latéralement : <span class=\"nc-blue nc-bold\">face interne de l’os iliaque</span> + relief des <strong><span class=\"nc-blue_bg nc-bold\">épines</span> <span class=\"nc-blue_bg nc-bold\">sciatiques</span></strong></li>\n              </ul>\n              <strong>Diamètres :</strong>\n              <ul>\n                <li>Constant à tous les plans : <span>≈ <span class=\"nc-pink nc-bold\">12 cm</span></span></li>\n                <li>Bisciatique/biépineux : <span><span class=\"nc-pink nc-bold\">10,5 cm</span></span> (<em>≠ bi-ischiatique</em>)</li>\n              </ul>\n              <strong>Détroit moyen :</strong> à l’union du 1/3 inférieur et des 2/3 supérieurs, passe par les 2 épines sciatiques<br>\n              <strong>Forme :</strong> cylindre coudé (segment de tore) avec 2 rétrécissements (promontoire + épines sciatiques)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Détroit inférieur (DI)</strong><br><em>= plan de dégagement</em></td>\n            <td>\n              <strong>Forme :</strong> prisme triangulaire\n              <ul>\n                <li>Face supérieure : plan du détroit moyen</li>\n                <li>Face <span class=\"nc-blue_bg nc-bold\">antérieure</span> : oblique bas/arrière, joint bord inférieur du pubis aux ischions</li>\n                <li>Face <span class=\"nc-blue_bg nc-bold\">postérieure</span> : oblique haut/arrière, déterminée par les 2 ischions et la pointe du coccyx</li>\n              </ul>\n              <strong><span>Diamètre</span> bi-ischiatique :</strong> <span>12 cm</span> (principale mesure ; <em>≠ bi-sciatique</em>)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Périnée — diaphragme pelvi-périnéal</h4>\n\n      <ul>\n        <li><span class=\"nc-pink_bg\">Bassin mou</span> = <strong><span class=\"nc-pink_bg\">vagin</span> + diaphragme pelvi-périnéal</strong></li>\n        <li><span class=\"nc-yellow_bg\">Expulsion = traversée du périnée</span> sous l’influence des <span>CU + <span class=\"nc-green nc-bold\">poussée abdominale maternelle</span></span></li>\n        <li><strong>Plan profond :</strong> faisceaux du muscle élévateur de l’anus + ligament sacrotubéral</li>\n        <li><strong>Plan superficiel :</strong> muscles du périnée superficiel</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong><span class=\"nc-yellow_bg\">Présentation</span> engagée.</strong> Une <span class=\"nc-yellow_bg\">présentation</span> est dite engagée lorsque <strong>le plus grand <span>diamètre</span> de la <span class=\"nc-yellow_bg\">présentation</span> a franchi le plan du DS</strong> (= <span class=\"nc-pink nc-bold\">diamètre bipariétal de </span><span><span class=\"nc-pink nc-bold\">9,5 cm</span></span> en <span class=\"nc-yellow_bg\">présentation</span> céphalique).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 25 — <span>Grossesse</span> extra-utérine · 23 — Grossesse normale · 24 — Complications de la grossesse</em></p></div>"},{"i":"66052f3e0677","n":31,"o":"31-2","u":"Définition","t":"Connaître les repères du mobile fœtal","q":"Que retenir concernant les repères du mobile fœtal ?","a":"<div class=\"notion-course\"><p>Le <span>mobile fœtal</span> est un ovoïde à 2 pôles (pelvien + céphalique) pelotonné sur lui-même. Ses dimensions conditionnent la possibilité de franchissement de la filière pelvienne.</p>\n\n      <h4>Tête fœtale</h4>\n\n      <table>\n        <thead>\n          <tr><th>Caractéristique</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Forme</strong></td>\n            <td>Ovoïde — petite extrémité = <strong><span class=\"nc-blue nc-bold\">menton</span></strong>, grosse extrémité = <strong>occiput</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Sutures</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-blue_bg\">Suture longitudinale</span> (sagittale) sur la ligne médiane</li>\n                <li><span class=\"nc-blue_bg\">Sutures transversales antérieure et postérieure</span> (coronale + lambdoïde)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Fontanelles</strong></td>\n            <td>\n              Au croisement entre suture longitudinale et transversale :\n              <ul>\n                <li><span>Fontanelle antérieure</span> = <strong><span class=\"nc-blue nc-bold\">bregma</span></strong> (bregmatique)</li>\n                <li><span>Fontanelle postérieure</span> = <strong><span class=\"nc-blue nc-bold\">lambda</span></strong> (lambdoïde)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Diamètres clés</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"nc-green nc-bold\">Bipariétal</span> :</strong> <span><span class=\"nc-pink nc-bold\">9,5 cm</span></span> — <span>diamètre</span> du passage de la tête</li>\n                <li><span class=\"nc-green nc-bold\">Sous-occipito-bregmatique</span> : <span><span class=\"nc-pink nc-bold\">9,5 cm</span></span> (favorable à l’engagement, tête bien fléchie)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Corps fœtal</h4>\n\n      <table>\n        <thead>\n          <tr><th><span>Diamètre</span></th><th>Valeur</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"nc-yellow_bg\">Biacromial</span></strong></td><td><span><span class=\"nc-pink nc-bold\">12 cm</span></span> réduit à <span>9,5 cm</span> par tassement (passage des épaules)</td></tr>\n          <tr><td>Bitrochantérien</td><td><span>9 cm</span></td></tr>\n          <tr><td>Bi-iliaque</td><td><span>8 cm</span></td></tr>\n          <tr><td>Sacro-pubien</td><td><span>7,5 cm</span></td></tr>\n          <tr><td>Sterno-dorsal</td><td><span>9,5 cm</span></td></tr>\n          <tr><td>Sacro-pré-tibial</td><td><span><span class=\"nc-pink nc-bold\">12 cm</span></span> réduit à <span>9 cm</span> par tassement</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong><span class=\"nc-yellow_bg\">Présentation</span> céphalique fléchie.</strong> Le <span>diamètre</span> céphalique varie selon la flexion. <strong>Tête en flexion maximale</strong> sur le tronc = <span class=\"nc-yellow_bg\">présentation</span> céphalique fléchie = <strong><span class=\"nc-blue_bg\">diamètre bipariétal</span></strong> qui conditionne l’engagement. L’accouchement est d’autant plus facile que la tête est bien fléchie.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span>Grossesse</span> normale · 34 — Suites de couches pathologiques</em></p></div>"},{"i":"de85dbbec020","n":31,"o":"31-3","u":"Définition","t":"Connaître les modifications de l’utérus liées à la grossesse et à l’accouchement","q":"Que retenir concernant les modifications de l’utérus liées à la grossesse et à l’accouchement ?","a":"<div class=\"notion-course\"><p>L’utérus subit des <span>modifications majeures</span> pendant la <span>grossesse</span> pour devenir le moteur de l’accouchement.</p>\n\n      <h4>3 parties de l’utérus gravide</h4>\n\n      <ul>\n        <li><strong>Corps</strong> — forme d’ovoïde à grosse extrémité supérieure en fin de <span>grossesse</span></li>\n        <li><strong>Segment inférieur</strong> — portion <em>propre à la gravidité</em>, <span>absent chez la femme non enceinte</span></li>\n        <li><strong>Col</strong> — contient 2 orifices : externe et interne</li>\n      </ul>\n\n      <h4>Segment inférieur (segment antérieur)</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Formation temporaire.</strong> N’apparaît qu’au <strong>3<sup>e</sup> trimestre</strong>, développé <strong>entre le corps et le col</strong> aux dépens de l’isthme utérin. En fin de travail : mesure <span>10 cm</span>, épaisseur de quelques millimètres seulement.\n        <ul>\n          <li><strong><span class=\"nc-green_bg\">Rôle</span> :</strong> recueille la force de la contraction utérine et la dirige sur le col</li>\n          <li><strong>Peu vascularisé</strong> et limité en haut par la zone de décollement du péritoine vésico-utérin</li>\n          <li><strong>Intérêt chirurgical fondamental :</strong> <span><span class=\"nc-pink nc-bold\">zone d’incision des césariennes segmentaires transversales</span></span></li>\n        </ul>\n      </div>\n\n      <h4>3 tuniques de l’utérus</h4>\n\n      <table>\n        <thead>\n          <tr><th>Tunique</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Séreuse</strong></td>\n            <td>Péritoine, particularité = se clive facilement au niveau du segment inférieur</td>\n          </tr>\n          <tr>\n            <td><strong>Muqueuse</strong></td>\n            <td>Transformée en <span>caduques</span> lors de la <span>grossesse</span></td>\n          </tr>\n          <tr>\n            <td><strong>Musculeuse (myomètre)</strong></td>\n            <td>\n              Fibres musculaires lisses disposées en 2 assises (externe + interne) de part et d’autre d’une <strong>couche plexiforme</strong> dont les faisceaux enserrent de nombreux vaisseaux.\n              <ul>\n                <li>Couche circulaire externe + faisceaux longitudinaux discontinus</li>\n                <li><span>Phénomène des ligatures vivantes</span> = la rétraction des fibres efface la lumière des vaisseaux au niveau de la couche plexiforme → <strong>réduit l’hémorragie de la délivrance</strong></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Axe &amp; dextrorotation</h4>\n\n      <ul>\n        <li><strong>Axe du corps utérin :</strong> en décubitus, axe de poussée utérine légèrement incliné vers l’avant par rapport à l’axe du DS</li>\n        <li><strong>Dextrorotation :</strong> dans le plan frontal, l’utérus est fréquemment incliné <strong>du côté droit</strong> (rotation sur axe vertical, face <span class=\"nc-blue_bg nc-bold\">antérieure</span> dirigée en avant et à droite)</li>\n      </ul>\n\n      <h4><span class=\"nc-yellow_bg\">Modifications du col</span> utérin</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Effacement puis dilatation.</strong>\n        <ul>\n          <li><strong><span class=\"nc-yellow_bg\">Effacement du col</span> :</strong> disparition progressive de <span class=\"nc-red nc-bold\">l’épaisseur</span> et de la <span class=\"nc-red nc-bold\">longueur</span> du col</li>\n          <li><strong><span class=\"nc-green nc-bold\">Dilatation</span> :</strong> orifice cervical s’élargit jusqu’à <span><span class=\"nc-red nc-bold\">10 cm</span></span> (<span class=\"nc-green nc-bold\">dilatation</span> complète)</li>\n          <li><span class=\"nc-green nc-bold\">Chez la </span><span><span class=\"nc-green nc-bold\">multipare</span></span> : <span class=\"nc-green nc-bold\">effacement et dilatation s’effectuent </span><strong><span class=\"nc-green nc-bold\">en même temps</span> ⭐</strong></li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span>Grossesse</span> normale · 34 — Suites de couches pathologiques</em></p></div>"},{"i":"bbc871b87bff","n":31,"o":"31-4","u":"Définition","t":"Connaître le rôle des contractions utérines et la manière de les surveiller","q":"Que retenir concernant le rôle des contractions utérines et la manière de les surveiller ?","a":"<div class=\"notion-course\"><p>Les <span><span class=\"nc-yellow_bg\">contractions utérines</span> (CU)</span> sont le <strong>moteur de l’accouchement</strong>. Elles assurent la <span class=\"nc-blue nc-bold\">dilatation</span> du col, la formation de la poche des eaux, et la <span class=\"nc-pink\">progression</span> du mobile fœtal.</p>\n\n      <h4>Caractéristiques des CU du travail</h4>\n\n      <ul>\n        <li><strong><span class=\"nc-green_bg\">Totales</span></strong> — intéressent tout l’utérus</li>\n        <li><strong><span class=\"nc-green_bg\">Involontaires</span></strong></li>\n        <li><strong>Intermittentes / répétées / rapprochées</strong> — chaque contraction précédée et suivie d’une période de repos</li>\n        <li><strong>Progressives</strong> dans leur durée, fréquence et intensité</li>\n        <li><strong><span class=\"nc-blue_bg\">Douloureuses</span></strong> — <span><span class=\"nc-pink nc-bold\">analgésie péridurale</span></span> = moyen le plus efficace pour les supprimer</li>\n      </ul>\n\n      <h4>Rôles physiologiques des CU</h4>\n\n      <table>\n        <thead>\n          <tr><th>Cible</th><th>Effet</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Col utérin</strong></td>\n            <td>\n              <ol>\n                <li><strong><span class=\"nc-yellow_bg\">Effacement</span></strong><span class=\"nc-yellow_bg\"> du col</span> : disparition progressive de <span class=\"nc-red nc-bold\">l’épaisseur</span> et de la <span class=\"nc-red nc-bold\">longueur</span></li>\n                <li><strong><span class=\"nc-green nc-bold\">Dilatation</span></strong> : élargissement progressif jusqu’à <span><span class=\"nc-red nc-bold\">10 cm</span></span></li>\n              </ol>\n              Chez la <span>multipare</span> : effacement et dilatation simultanés ⭐\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Poche des eaux</strong></td>\n            <td>\n              Constitution par décollement des membranes au cours du travail. <strong>Double rôle :</strong>\n              <ul>\n                <li><span class=\"nc-green_bg\">Protecteur</span> : œuf <span>vs</span> <strong><span class=\"nc-green nc-bold\">infection</span></strong>, fœtus <span>vs</span> <strong><span class=\"nc-green nc-bold\">traumatisme</span></strong></li>\n                <li><span class=\"nc-green_bg\">Mécanique</span> : <strong><span class=\"nc-green nc-bold\">aide à la dilatation cervicale</span></strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Mobile fœtal</strong></td>\n            <td>Permet le franchissement des étages de la filière pelvi-génitale (DS → excavation → DI → périnée)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span>Surveillance</span> des CU — <span class=\"nc-blue_bg\">Tocographie</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Méthode</th><th>Apport</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Tocographie externe</strong></td>\n            <td>Capteur externe → note la <strong>durée</strong> et la <strong>fréquence</strong> des CU</td>\n          </tr>\n          <tr>\n            <td><strong>Tocographie interne</strong></td>\n            <td>\n              Cathéter fin et souple introduit par voie transcervicale dans la cavité utérine →\n              <ul>\n                <li><strong>Tonus de base</strong></li>\n                <li><strong>Pression intra-utérine</strong></li>\n              </ul>\n              Peut être intra- ou extra-amniotique selon que les membranes sont rompues\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Cardiotocographie (CTG)</strong></td>\n            <td>Enregistrement <strong>simultané</strong> du <span>RCF</span> + des CU — continu pendant les 2 premières étapes</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Anomalies des CU à reconnaître.</strong>\n        <ul>\n          <li><span>Hypocinésie</span> — CU insuffisantes (fréquence/intensité)</li>\n          <li><span>Hypercinésie</span> — CU excessives</li>\n          <li><span>Hypotonie</span> — tonus de base trop bas</li>\n          <li><span>Hypertonie</span> — tonus de base trop élevé (risque d’<strong><span>hypoxie fœtale</span></strong>)</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 24 — Complications de la <span>grossesse</span></em></p></div>"},{"i":"4dd90b18ba91","n":31,"o":"31-5","u":"Définition","t":"Connaître les définitions des différents types d’accouchement","q":"Que retenir concernant les définitions des différents types d’accouchement ?","a":"<div class=\"notion-course\"><p>L’<span>accouchement</span> = ensemble des phénomènes aboutissant à l’expulsion du fœtus et des annexes hors du ventre maternel (fœtus + placenta + liquide amniotique + membranes).</p>\n\n      <h4>Définitions fondamentales</h4>\n\n      <ul>\n        <li><strong>Accouchement normal</strong> = débute <span>spontanément</span> (≠ déclenchement du travail)</li>\n        <li>Le fœtus doit franchir <strong>3 obstacles</strong> : <span>col utérin</span> + <span>bassin</span> + <span>périnée</span></li>\n        <li>Les <strong><span class=\"nc-yellow_bg\">contractions utérines</span></strong> sont le moteur de l’accouchement</li>\n      </ul>\n\n      <h4>Eutocique <span>vs</span> <span class=\"nc-red nc-bold\">Dystocique</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Type</th><th>Définition</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Eutocique</strong></td>\n            <td>Expulsion par <strong>voie basse</strong> par la <em>seule influence des phénomènes naturels</em></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-red nc-bold\">Dystocique</span></strong></td>\n            <td>Entraîne des <span>difficultés ou impossibilités d’accouchement par voie basse</span> (nécessite manœuvres instrumentales ou césarienne)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Spontané <span>vs</span> Déclenché</h4>\n\n      <ul>\n        <li><strong>Accouchement spontané</strong> — travail démarre de lui-même</li>\n        <li><strong>Accouchement déclenché</strong> — induction du travail pour raison médicale (dépassement de terme, RPM, pathologie maternelle ou fœtale)</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Voies de naissance.</strong>\n        <ul>\n          <li><span>Voie basse</span> — accouchement vaginal (eutocique ou avec extraction instrumentale : forceps, ventouse, spatules)</li>\n          <li><span>Voie haute</span> — <strong>césarienne</strong> (programmée ou en <span>urgence</span>)</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 24 — Complications de la <span>grossesse</span></em></p></div>"},{"i":"ba9f5b2fc298","n":31,"o":"31-6","u":"Définition","t":"Connaître les différentes étapes de l’accouchement","q":"Que retenir concernant les différentes étapes de l’accouchement ?","a":"<div class=\"notion-course\"><p>L’accouchement se déroule en <span>4 étapes</span> séquentielles. Connaître leur succession et leur durée est indispensable pour suivre la progression du travail.</p>\n\n      <h4>Vue d’ensemble — 4 étapes</h4>\n\n      <table>\n        <thead>\n          <tr><th>Étape</th><th>Début</th><th>Fin</th><th>Durée</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1<sup>re</sup> étape</strong><br><em>Dilatation du col</em></td>\n            <td>Début du vrai travail</td>\n            <td><span class=\"nc-green nc-bold\">Dilatation</span> complète (<span><span class=\"nc-red nc-bold\">10 cm</span></span>)</td>\n            <td>\n              <ul>\n                <li>Primipare : <span>6–18 h</span></li>\n                <li>Multipare : <span>2–10 h</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>2<sup>e</sup> étape</strong><br><em>Expulsion</em></td>\n            <td>Fin de la <span class=\"nc-green nc-bold\">dilatation</span> du col</td>\n            <td><span class=\"nc-yellow_bg\">Naissance de l’enfant</span></td>\n            <td><span>3–4 h maximum</span></td>\n          </tr>\n          <tr>\n            <td><strong>3<sup>e</sup> étape</strong><br><em>Délivrance</em></td>\n            <td><span class=\"nc-yellow_bg\">Naissance de l’enfant</span></td>\n            <td>Expulsion du placenta et des membranes</td>\n            <td><span>5–30 min</span></td>\n          </tr>\n          <tr>\n            <td><strong>4<sup>e</sup> étape</strong><br><em>Post-partum immédiat</em></td>\n            <td>Délivrance</td>\n            <td>Stabilisation des constantes maternelles</td>\n            <td><span>2 h</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Découpage du 1<sup>er</sup> <span>stade</span></h4>\n\n      <ul>\n        <li><strong>Phase de latence</strong> — début du travail jusqu’à <span class=\"nc-green nc-bold\">dilatation</span> cervicale de <span>5–6 cm</span></li>\n        <li><strong>Phase active</strong> — de <span>5–6 cm</span> jusqu’à <span class=\"nc-green nc-bold\">dilatation</span> complète (<span><span class=\"nc-red nc-bold\">10 cm</span></span>)</li>\n      </ul>\n\n      <h4>Découpage du 2<sup>e</sup> <span>stade</span></h4>\n\n      <ul>\n        <li><strong>Phase de descente</strong> (passive) — de la <span class=\"nc-green nc-bold\">dilatation</span> complète jusqu’au début des <span class=\"nc-brown_bg\">efforts expulsifs</span></li>\n        <li><strong>Phase d’expulsion</strong> (active) — entre le début des <span class=\"nc-brown_bg\">efforts expulsifs</span> et la naissance</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Influence de la parité.</strong> La durée du travail est plus longue chez les <span>nullipares</span> que chez les <span>multipares</span>. Chez une même femme, la durée se raccourcit avec la parité. <span>Grande <span class=\"nc-green nc-bold\">multipare</span> → risque d’accouchement à domicile</span> (travail très rapide).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : obj-6 (description détaillée des étapes)</em></p></div>"},{"i":"8946ea1da450","n":31,"o":"31-7","u":"Définition","t":"Connaître la description des différentes étapes du travail","q":"Que retenir concernant la description des différentes étapes du travail ?","a":"<div class=\"notion-course\"><p>La description détaillée du travail comporte <span>3 stades</span> obstétricaux, avec des phases internes définissant la cinétique de la dilatation et de la descente fœtale.</p>\n\n      <h4>1<sup>er</sup> <span>stade</span> — Dilatation du col</h4>\n\n      <div class=\"callout callout-info\">\n        <strong><span>Diagnostic positif</span> du début du travail.</strong> Association de :\n        <ul>\n          <li><strong><span class=\"nc-yellow_bg\">Modifications du col</span> :</strong> <span class=\"nc-red nc-bold\">raccourcissement</span>, ramollissement, <span class=\"nc-red nc-bold\">ouverture jusqu’à dilatation complète</span> (<span><span class=\"nc-red nc-bold\">10 cm</span></span>)</li>\n          <li><strong>CU du travail</strong> (par interrogatoire / palpation / <span class=\"nc-blue_bg\">tocographie</span>) : <span class=\"nc-green_bg\">totales</span>, <span class=\"nc-green_bg\">involontaires</span>, intermittentes/répétées, progressives, <span class=\"nc-blue_bg\">douloureuses</span></li>\n        </ul>\n      </div>\n\n      <p><span><span class=\"nc-blue_bg\">Perte du « bouchon muqueux »</span></span><span class=\"nc-blue_bg\"> précède souvent le début du travail</span> (écoulement de <strong><span class=\"nc-blue nc-bold\">glaires épaisses et brunâtres</span></strong> par la vulve).</p>\n\n      <table>\n        <thead>\n          <tr><th>Phase</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Phase de latence</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-green nc-bold\">Dilatation</span> jusqu’à <span>5–6 cm</span></li>\n                <li>Succède à l’effacement (parallèle <span class=\"nc-green nc-bold\">chez la multipare</span> ⭐)</li>\n                <li>Début du travail = <strong>&gt; 2 CU pour <span>10 min</span></strong></li>\n                <li>Phase <strong>la plus longue</strong> (parfois <span class=\"nc-pink nc-bold\">&gt; </span><span><span class=\"nc-pink nc-bold\">10 h</span></span> chez la nullipare)</li>\n                <li><em>Ancien réf. :</em> moyenne <span>8,5 h</span> primipare / <span>5,5 h</span> multipare ; max <span>20 h</span> / <span>14 h</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Phase active</strong></td>\n            <td>\n              Après <span>5–6 cm</span>, vitesse de dilatation <span>anormale</span> ⚠️ si :\n              <ul>\n                <li>Entre <span>5–7 cm</span> : <strong><span class=\"nc-red nc-bold\">&lt; </span><span><span class=\"nc-red nc-bold\">1 cm</span></span><span class=\"nc-red nc-bold\"> / </span><span><span class=\"nc-red nc-bold\">4 h</span></span></strong></li>\n                <li>Entre <span>7 cm</span> et dilatation complète : <strong><span class=\"nc-red nc-bold\">&lt; </span><span><span class=\"nc-red nc-bold\">1 cm</span></span><span class=\"nc-red nc-bold\"> / </span><span><span class=\"nc-red nc-bold\">2 h</span></span></strong></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Poche des eaux — types de <span>rupture</span></h4>\n\n      <ul>\n        <li><strong>Spontanée</strong> — pendant le travail, sans intervention</li>\n        <li><strong>Artificielle (<span>amniotomie</span>)</strong> — <span>rupture</span> volontaire pour aider le travail (stagnation de la dilatation avec membranes intactes)</li>\n        <li><strong>Tempestive</strong> — à dilatation complète</li>\n        <li><strong>Intempestive</strong> — avant dilatation complète</li>\n        <li><span><strong>Prématurée (RPM)</strong></span> — <strong>avant tout travail</strong>, <strong><span class=\"nc-red nc-bold\">risque </span><span><span class=\"nc-red nc-bold\">infectieux</span></span> ⚠️</strong></li>\n      </ul>\n\n      <h4>2<sup>e</sup> <span>stade</span> — Naissance</h4>\n\n      <ul>\n        <li><strong>Phase de descente (passive)</strong> — de la <span class=\"nc-green nc-bold\">dilatation</span> complète jusqu’au début des <span class=\"nc-brown_bg\">efforts expulsifs</span></li>\n        <li><strong>Phase d’expulsion (active)</strong> — du début des <span class=\"nc-brown_bg\">efforts expulsifs</span> jusqu’à la naissance</li>\n      </ul>\n\n      <h4>3<sup>e</sup> <span>stade</span> — Délivrance</h4>\n\n      <p>De la <span class=\"nc-yellow_bg\">naissance de l’enfant</span> jusqu’à l’expulsion du placenta. Durée normale : <span>5–30 min</span>. Au-delà de <span>30 min</span> → <span class=\"nc-yellow_bg\">délivrance</span> artificielle.</p>\n\n      <h4><span>Surveillance</span> — <span>antibioprophylaxie</span> SGB</h4>\n\n      <div class=\"callout callout-info\">\n        <strong><span>Antibioprophylaxie</span> SGB</strong> chez les femmes à risque (portage <span>Streptocoque B</span>) : <span>pénicilline G</span>, <span>amoxicilline</span>, <span>ampicilline</span> ou <span>céfazoline</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : obj-5 (vue d’ensemble étapes) · obj-12 (délivrance)</em></p></div>"},{"i":"c02adcde52b4","n":31,"o":"31-8","u":"Diagnostic positif","t":"Connaître les éléments de surveillance clinique de l’accouchement normal","q":"Que retenir concernant les éléments de surveillance clinique de l’accouchement normal ?","a":"<div class=\"notion-course\"><p>La <span>surveillance</span> clinique de l’accouchement repose sur un faisceau d’éléments cliniques et paracliniques reportés sur le <span><span class=\"nc-blue nc-bold\">partogramme</span></span>, <span class=\"nc-pink nc-bold\">au minimum </span><strong><span class=\"nc-pink nc-bold\">toutes les heures</span></strong>.</p>\n\n      <h4>Examen clinique maternel</h4>\n\n      <table>\n        <thead>\n          <tr><th>Élément</th><th>Modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Analgésie</strong></td>\n            <td>Anesthésie péridurale possible en <span class=\"nc-yellow_bg nc-bold\">début de travail</span></td>\n          </tr>\n          <tr>\n            <td><strong>Abdomen</strong></td>\n            <td>Palpation = présentation fœtale (longitudinale/transversale) par recherche du pôle céphalique et du plan du dos</td>\n          </tr>\n          <tr>\n            <td><strong>Hauteur utérine</strong></td>\n            <td>Mesurée <strong>en dehors d’une CU</strong> — moyenne <span><span class=\"nc-pink nc-bold\">33 cm</span></span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-blue_bg\">Toucher vaginal</span> (<span>TV</span>)</strong></td>\n            <td>\n              Réalisé avec asepsie <strong>toutes les <span>30 min</span> à <span>1 h</span></strong>. Renseigne sur :\n              <ul>\n                <li>Diagnostic et variété de présentation</li>\n                <li>État de la poche des eaux (présence ou non de membranes)</li>\n                <li>État du col par <span>score de Bishop</span> : <strong><span class=\"nc-blue nc-bold\">dilatation</span> · <span class=\"nc-blue nc-bold\">effacement</span> · <span class=\"nc-blue nc-bold\">consistance</span> · <span class=\"nc-blue nc-bold\">position</span> du col · <span class=\"nc-blue nc-bold\">positionnement</span> de la présentation fœtale</strong> (5 critères)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span>Score</span> de Bishop</h4>\n\n      <div class=\"callout callout-info\">\n        <strong><span>Score</span> de Bishop</strong> — évalue la <strong>maturation du col</strong> en 5 critères côtés 0–2 ou 0–3 (sur 13). Détermine l’éligibilité au déclenchement du travail.\n      </div>\n\n      <h4>Poche des eaux &amp; liquide amniotique</h4>\n\n      <table>\n        <thead>\n          <tr><th>Situation</th><th>CAT</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Membranes intactes</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"nc-green_bg\">Conservation</span></strong><span class=\"nc-green_bg\"> de l’intégrité de la poche des eaux</span>, OU</li>\n                <li><strong><span>Rupture</span> artificielle</strong> si <span><span class=\"nc-blue nc-bold\">dilatation</span> <span class=\"nc-pink nc-bold\">&gt; 6 cm</span></span> ET <strong>présentation engagée</strong></li>\n                <li>Après <span>rupture</span> : <span>réexaminer la parturiente pour vérifier l’absence de <span class=\"nc-red nc-bold\">procidence du cordon</span></span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>RPM</strong> (<span><span class=\"nc-red_bg\">rupture</span></span><span class=\"nc-red_bg\"> prématurée</span>)</td>\n            <td>\n              Pas de poche des eaux. Risques :\n              <ul>\n                <li><span>Infection</span></li>\n                <li><span><span class=\"nc-red nc-bold\">Procidence du cordon</span></span> (cordon ombilical devant la présentation)</li>\n              </ul>\n              CAT : <strong><span>hospitalisation</span> immédiate 🏥</strong>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Couleur du liquide amniotique</h4>\n\n      <ul>\n        <li><strong>Normale</strong> — <span class=\"nc-green nc-bold\">clair</span>, <span class=\"nc-green nc-bold\">transparent</span>, <span class=\"nc-green nc-bold\">lactescent</span></li>\n        <li><strong>Épais ou teinté</strong> — en faveur d’une <span><span class=\"nc-red nc-bold\">chorioamniotite</span></span></li>\n        <li><strong>Vert ± sombre (méconial)</strong> — <span><span class=\"nc-red nc-bold\">signe d’état fœtal non rassurant</span></span> (toute émission de méconium avant l’accouchement traduit une pathologie)</li>\n      </ul>\n\n      <h4><span>Surveillance</span> fœtale</h4>\n\n      <ul>\n        <li><strong><span>Échographie</span></strong> en salle de travail : confirme l’examen obstétrical, estime la quantité de LA, localise le placenta, confirme la présentation</li>\n        <li><strong>Cardiotocographe (CTG)</strong> — enregistrement <strong>simultané</strong> :\n          <ul>\n            <li><span>RCF</span> — <strong>continu pendant les 2 premières étapes</strong></li>\n            <li><span><span class=\"nc-blue_bg\">Tocographie</span></span> — caractéristiques des CU (anomalies = hypocinésie, hypercinésie, hypotonie, hypertonie)</li>\n          </ul>\n        </li>\n        <li><strong><span><span class=\"nc-blue_bg\">ECG</span></span><span class=\"nc-blue_bg\"> fœtal</span></strong> ou <strong><span><span class=\"nc-blue_bg\">pH au scalp</span></span></strong> — autres moyens de <span>surveillance</span> fœtale</li>\n      </ul>\n\n      <h4><span>Surveillance</span> du 4<sup>e</sup> <span>stade</span></h4>\n\n      <div class=\"callout callout-warn\">\n        <strong>Post-partum immédiat — <span>2 h</span> en salle de travail.</strong>\n        <ul>\n          <li><span>Surveillance</span> <strong>constante</strong> de l’accouchée pendant <span><span class=\"nc-pink nc-bold\">2 h après la délivrance</span></span></li>\n          <li><strong><span class=\"nc-blue_bg\">Expression utérine</span></strong> 2–3 fois : <em><span class=\"nc-blue nc-bold\">empaumer l’utérus à pleine main</span> et appuyer vers le bas</em> → évacue les caillots situés dans l’utérus et le vagin</li>\n        </ul>\n      </div>\n\n      <h4>Prévention de l’allo-immunisation Rh</h4>\n\n      <table>\n        <thead>\n          <tr><th>Situation</th><th>CAT</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Phénotype <span>RhD</span> du nouveau-né non connu</strong></td>\n            <td><span class=\"nc-blue_bg\">Contrôle du groupe Rh sur sang du cordon</span></td>\n          </tr>\n          <tr>\n            <td><strong>Mère Rh+ confirmé au <span>génotypage de grossesse</span></strong></td>\n            <td><span><span class=\"nc-red nc-bold\">Aucun contrôle supplémentaire</span></span></td>\n          </tr>\n          <tr>\n            <td><strong>Mère Rh− + enfant Rh−</strong></td>\n            <td>Rien à faire après contrôle</td>\n          </tr>\n          <tr>\n            <td><strong>Mère Rh− + enfant Rh+</strong></td>\n            <td>\n              <ol>\n                <li><strong><span>Test de Kleihauer</span></strong> sur sang maternel <strong><span>≥ 30 min</span> après la délivrance</strong></li>\n                <li><strong><span class=\"nc-pink_bg\">Prophylaxie anti-D</span></strong><span class=\"nc-pink_bg\"> chez la mère dans les</span> <span><span class=\"nc-pink_bg nc-bold\">&lt; 72 h</span></span> (posologie ajustée au Kleihauer)</li>\n                <li>Injection possible <strong><span class=\"nc-pink nc-bold\">jusqu’à </span><span><span class=\"nc-pink nc-bold\">30 jours</span></span><span class=\"nc-pink nc-bold\"> après l’accouchement</span></strong> si oubli <span class=\"nc-pink_bg nc-bold\">&lt; </span><span><span class=\"nc-pink_bg nc-bold\">72 h</span></span></li>\n              </ol>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span>Grossesse</span> normale · 24 — Complications de la grossesse</em></p></div>"},{"i":"31453f999102","n":31,"o":"31-9","u":"Contenu multimédia","t":"Engagement de la tête fœtale","q":"Que retenir concernant engagement de la tête fœtale ?","a":"<div class=\"notion-course\"><p>L’<span>engagement</span> = <strong><span class=\"nc-yellow_bg\">franchissement du DS par le plus grand </span><span><span class=\"nc-yellow_bg\">diamètre</span></span><span class=\"nc-yellow_bg\"> de la présentation</span></strong>. C’est le 1<sup>er</sup> temps de la traversée de la filière pelvienne et l’étape qui conditionne le plus souvent la possibilité d’accouchement par voie basse.</p>\n\n      <h4>Définition opérationnelle</h4>\n\n      <div class=\"callout callout-info\">\n        <strong><span class=\"nc-yellow_bg\">Présentation</span> engagée</strong> = sa <strong>plus grande circonférence</strong> a franchi le DS. En <span class=\"nc-yellow_bg\">présentation</span> céphalique fléchie, cela correspond au passage du <span><span class=\"nc-pink nc-bold\">diamètre bipariétal de 9,5 cm</span></span>.\n      </div>\n\n      <h4>Accommodation de la tête fœtale au DS — 4 opérations</h4>\n\n      <ol>\n        <li><strong><span class=\"nc-green_bg\">Flexion du sommet</span></strong> — les dimensions les plus favorables sont <strong><span class=\"nc-green nc-bold\">sous-occipito-bregmatique</span> + <span class=\"nc-green nc-bold\">bipariétal</span></strong></li>\n        <li><strong><span class=\"nc-green_bg\">Orientation en oblique</span></strong> — les diamètres les plus utilisables du DS sont les <strong><span class=\"nc-green nc-bold\">diamètres obliques</span></strong></li>\n        <li><strong>Asynclitisme</strong> — inclinaison latérale (facultatif)</li>\n        <li><strong><span class=\"nc-brown_bg\">Déformations plastiques</span></strong> — modelage de la tête (facultatif)</li>\n      </ol>\n\n      <h4>Forces en jeu (ancien référentiel)</h4>\n\n      <ul>\n        <li>Force de poussée (P) de la CU fait avec l’axe du DS un angle de <span>30–50°</span></li>\n        <li>P se décompose en :\n          <ul>\n            <li><strong>Force de <span class=\"nc-pink\">progression</span> (G)</strong> — perpendiculaire à l’axe du DS</li>\n            <li><strong>Force de <span class=\"nc-pink\">résistance</span> (R)</strong> — parallèle à l’axe, participe à la flexion et à l’<span class=\"nc-green_bg\">orientation en oblique</span></li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4>Diagnostic clinique de l’engagement</h4>\n\n      <table>\n        <thead>\n          <tr><th>Type d’examen</th><th>Signes</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Symptômes maternels</strong></td>\n            <td><span class=\"nc-green_bg\">Femme respire plus librement</span> (mobile descendu), mais <span class=\"nc-blue_bg\">gêne s’accentue du côté des organes pelviens</span></td>\n          </tr>\n          <tr>\n            <td><strong>Hauteur utérine</strong></td>\n            <td><strong><span class=\"nc-pink nc-bold\">Diminué de quelques centimètres</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong>Palpation abdominale</strong></td>\n            <td>\n              <ul>\n                <li><strong><span><span class=\"nc-yellow_bg\">Signe de Le Lorier</span></span></strong> — engagée si <strong><span class=\"nc-pink nc-bold\">2 doigts</span></strong> ne tiennent pas entre <span class=\"nc-blue nc-bold\">épaule antérieure du fœtus</span> et <span class=\"nc-blue nc-bold\">bord supérieur du pubis</span></li>\n                <li><strong><span><span class=\"nc-yellow_bg\">Signe de Favre</span></span></strong> — engagée si distance épaule <span class=\"nc-blue_bg nc-bold\">antérieure</span> ↔ <span class=\"nc-blue nc-bold\">bord supérieur du pubis</span> <span class=\"nc-pink nc-bold\">&lt; </span><span><span class=\"nc-pink nc-bold\">7 cm</span></span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-blue_bg\">Toucher vaginal</span></strong></td>\n            <td>\n              <ul>\n                <li><strong><span><span class=\"nc-yellow_bg\">Signe de Farabeuf</span></span></strong> — engagée si <strong><span class=\"nc-pink nc-bold\">2 doigts</span></strong> seulement entre pôle céphalique et plan sacro-coccygien</li>\n                <li><strong><span><span class=\"nc-yellow_bg\">Signe de Demelin</span></span></strong> — engagée si index introduit perpendiculairement à la face <span class=\"nc-blue_bg nc-bold\">antérieure</span> de la SP, parallèlement à son bord inférieur, <strong>vient buter contre la présentation</strong></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Position par rapport aux <span class=\"nc-blue_bg nc-bold\">épines</span> <span class=\"nc-blue_bg nc-bold\">sciatiques</span></h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Référentiel des épines sciatiques.</strong>\n        <ul>\n          <li><span>Niveau 0</span> — sommet au niveau des <span class=\"nc-blue_bg nc-bold\">épines</span> = <strong>tête fœtale engagée</strong></li>\n          <li><span>Niveaux –1 à –5</span> — sommet <span>1 à 5 cm</span> <strong>au-dessus</strong> du plan des <span class=\"nc-blue_bg nc-bold\">épines</span></li>\n          <li><span>Niveaux +1 à +5</span> — sommet <span>1 à 5 cm</span> <strong>en-dessous</strong> du plan des <span class=\"nc-blue_bg nc-bold\">épines</span></li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-warn\">Repère de lecture : l’occiput oriente la variété de <span class=\"nc-blue nc-bold\">position</span> ; flexion, engagement <span class=\"nc-blue_bg\">puis</span> descente et rotation sont des phénomènes distincts. Les détails sont reliés au parcours interactif de l’accouchement.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : obj-9 (orientation) · obj-1 (mobile fœtal)</em></p></div>"},{"i":"200ebcd06aa0","n":31,"o":"31-10","u":"Contenu multimédia","t":"Orientation de la tête fœtale","q":"Que retenir concernant orientation de la tête fœtale ?","a":"<div class=\"notion-course\"><p>L’<span>orientation</span> = position d’engagement définie par l’orientation à <strong>gauche / droite</strong> et <strong><span class=\"nc-blue_bg nc-bold\">antérieure</span> / <span class=\"nc-blue_bg nc-bold\">postérieure</span></strong> du dos du fœtus (occiput = repère). Les <span class=\"nc-green nc-bold\">diamètres obliques</span> du DS sont les plus utilisables.</p>\n\n      <h4>Position d’engagement — variétés</h4>\n\n      <table>\n        <thead>\n          <tr><th>Variété</th><th>Sigle</th><th>Fréquence</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Occipito-iliaque gauche antérieure</td><td><strong><span class=\"nc-yellow_bg\">OIGA</span></strong> ⭐</td><td><span>57 %</span> — <strong>la plus fréquente d’engagement</strong></td></tr>\n          <tr><td>Occipito-iliaque droite postérieure</td><td><strong><span class=\"nc-yellow_bg\">OIDP</span></strong></td><td><span>33 %</span></td></tr>\n          <tr><td>Occipito-iliaque gauche postérieure</td><td>OIGP</td><td><span>6 %</span></td></tr>\n          <tr><td>Occipito-iliaque droite antérieure</td><td>OIDA</td><td><span>4 %</span></td></tr>\n          <tr><td>Occipito-iliaque gauche transverse</td><td><span class=\"nc-red\">OIGT</span></td><td>variété accessoire</td></tr>\n          <tr><td>Occipito-iliaque droite transverse</td><td><span class=\"nc-red\">OIDT</span></td><td>variété accessoire</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Ne pas confondre — Engagement <span>vs</span> Dégagement.</strong>\n        <ul>\n          <li>Présentation d’<strong>engagement</strong> : <span>OIGA</span> (la plus fréquente)</li>\n          <li>Présentation de <strong>dégagement</strong> : <span>OP</span> (occipito-pubienne, la plus fréquente)</li>\n        </ul>\n        📝 Piège classique en obstétrique — facile d’inverser engagement et dégagement.\n      </div>\n\n      <h4>Types de présentation et diamètres</h4>\n\n      <table>\n        <thead>\n          <tr><th>Présentation</th><th>Repère</th><th><span>Diamètre</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Sommet</strong> (tête hyperfléchie)</td>\n            <td>Occiput</td>\n            <td><span class=\"nc-green nc-bold\">Bipariétal</span> — <span><span class=\"nc-pink nc-bold\">9,5 cm</span></span></td>\n          </tr>\n          <tr>\n            <td><strong>Face</strong> (tête totalement défléchie)</td>\n            <td><span class=\"nc-blue nc-bold\">Menton</span></td>\n            <td>Sous-mento-bregmatique — <span><span class=\"nc-pink nc-bold\">9,5 cm</span></span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-red nc-bold\">Front</span></strong> (flexion intermédiaire)</td>\n            <td>Nez</td>\n            <td>Syncipito-mentonnier — <span><span class=\"nc-red nc-bold\">césarienne requise</span></span></td>\n          </tr>\n          <tr>\n            <td><strong>Bregma</strong> (flexion intermédiaire)</td>\n            <td>—</td>\n            <td>Occipito-frontal</td>\n          </tr>\n          <tr>\n            <td><strong>Siège</strong></td>\n            <td><span class=\"nc-blue_bg\">Sacrum</span></td>\n            <td>Sacro-prétibial + bi-trochantérien</td>\n          </tr>\n          <tr>\n            <td><strong>Transversale (épaule)</strong></td>\n            <td>Acromion</td>\n            <td><span><span class=\"nc-red nc-bold\">Césarienne requise</span></span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Rotation dans l’excavation</h4>\n\n      <p>Les <span class=\"nc-blue nc-bold\">rotations tendent à ramener l’</span><strong><span class=\"nc-blue nc-bold\">occiput en avant</span></strong> (OP) :</p>\n\n      <ul>\n        <li><strong>Variétés antérieures</strong> (<span class=\"nc-green_bg\">OIGA</span>, <span class=\"nc-pink nc-bold\">OIDA</span>) → rotation de <span>45°</span> vers l’avant (OP)</li>\n        <li><strong><span>97 %</span> des variétés postérieures</strong> (<span class=\"nc-pink nc-bold\">OIDP</span>, <span class=\"nc-green_bg\">OIGP</span>) → grande rotation de <span>135°</span> vers l’avant (OP)</li>\n        <li><strong><span>3 %</span> des variétés postérieures</strong> → rotation au plus court vers l’arrière en occipito-sacré (OS), <span>45°</span></li>\n      </ul>\n\n      <div class=\"callout callout-warn\">Repère de lecture : l’occiput oriente la variété de <span class=\"nc-blue nc-bold\">position</span> ; flexion, engagement <span class=\"nc-blue_bg\">puis</span> descente et rotation sont des phénomènes distincts. Les détails sont reliés au parcours interactif de l’accouchement.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : obj-8 (engagement) · obj-1 (mobile fœtal)</em></p></div>"},{"i":"029973e9a81f","n":31,"o":"31-11","u":"Définition","t":"Connaître les mécanismes périnéaux du dégagement de la tête fœtale","q":"Que retenir concernant les mécanismes périnéaux du dégagement de la tête fœtale ?","a":"<div class=\"notion-course\"><p>Le <span>dégagement</span> commence quand la tête du fœtus est à la partie basse de l’excavation et se termine avec la naissance. Il se déroule en 3 étapes périnéales successives.</p>\n\n      <h4>3 étapes du dégagement céphalique</h4>\n\n      <table>\n        <thead>\n          <tr><th>Étape</th><th>Phénomènes périnéaux</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1. <span class=\"nc-yellow_bg\">Distension du périnée postérieur</span></strong></td>\n            <td>\n              <ul>\n                <li><strong>Hyperflexion de la tête</strong> accentue la descente</li>\n                <li><strong>Rétropulsion du coccyx</strong> → agrandit le <span>diamètre</span> antéro-postérieur du DI de <span><span class=\"nc-pink nc-bold\">9 à 11 cm</span></span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>2. <span class=\"nc-yellow_bg\">Distension du périnée antérieur</span></strong></td>\n            <td>\n              <ul>\n                <li><strong>Noyau fibreux du périnée</strong> abordé de front, refoulé par la présentation qui s’en coiffe</li>\n                <li>Laminage et distension en tous sens</li>\n                <li><strong>Distance ano-vulvaire triple ou quadruple</strong></li>\n                <li>La vulve s’oriente directement « en avant »</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>3. <span class=\"nc-yellow_bg\">Dégagement de la présentation</span></strong></td>\n            <td>\n              <strong>Soit dégagement occipito-pubien (OP)</strong> — le plus fréquent (occiput s’appuie sur la SP)\n              <ol>\n                <li>Partie sous-occipitale se fixe sous la symphyse → point de rotation pour la <strong><span class=\"nc-blue_bg nc-bold\">déflexion</span></strong></li>\n                <li>Opérateur contrôle l’expulsion (main sur le sommet de la tête)</li>\n                <li><span class=\"nc-blue_bg nc-bold\">Déflexion</span> progressive : <strong><span class=\"nc-blue nc-bold\">bosses frontales</span> → <span class=\"nc-blue nc-bold\">yeux</span> → <span class=\"nc-blue nc-bold\">nez</span> → <span class=\"nc-blue nc-bold\">bouche</span> → <span class=\"nc-blue nc-bold\">menton</span></strong></li>\n                <li>Épisiotomie <strong>parfois nécessaire</strong>, <span>non systématique</span></li>\n              </ol>\n              <strong>Soit dégagement occipito-sacré (OS)</strong> — rare (occiput s’appuie contre le sacrum)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Asynclitisme et <span class=\"nc-brown_bg\">déformations plastiques</span></h4>\n\n      <ul>\n        <li><strong>Asynclitisme</strong> — inclinaison latérale facultative du sommet pour faciliter le passage</li>\n        <li><strong><span class=\"nc-brown_bg\">Déformations plastiques</span></strong> — modelage des os du crâne fœtal grâce aux sutures et fontanelles (bosse séro-sanguine possible)</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Rôle de l’opérateur.</strong> Contrôle de la sortie par une main sur le sommet pour <strong>éviter une expulsion brutale</strong> (déchirures périnéales). Épisiotomie discutée au cas par cas.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : obj-11 (techniques de poussée et dégagement) · obj-7 (<span>surveillance</span>)</em></p></div>"},{"i":"edb9e58a8802","n":31,"o":"31-12","u":"Prise en charge","t":"Connaître les techniques de poussée et de dégagement","q":"Que retenir concernant les techniques de poussée et de dégagement ?","a":"<div class=\"notion-course\"><p>Les <span>techniques de poussée</span> sont à connaître pour accompagner efficacement la 2<sup>e</sup> étape du travail. La poussée doit être <strong>synchrone des CU</strong>, et les <span class=\"nc-brown_bg\">efforts expulsifs</span> ne doivent pas excéder <span>30 minutes</span>.</p>\n\n      <h4>Conditions préalables à l’expulsion</h4>\n\n      <ul>\n        <li><span>Surveillance</span> cardiotocographique <strong>maintenue en continu</strong></li>\n        <li><strong>Vessie <span class=\"nc-green_bg nc-bold\">vidée</span></strong> <span class=\"nc-green_bg\">préalablement</span></li>\n        <li><span class=\"nc-green_bg\">Installation en </span><strong><span class=\"nc-green_bg\">position</span> <span class=\"nc-green_bg nc-bold\">demi-assise</span></strong> si expulsion imminente</li>\n      </ul>\n\n      <h4>Physiologie de la poussée</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Réflexe de poussée.</strong> L’envie de pousser est déterminée par le <strong>contact de la <span class=\"nc-yellow_bg\">présentation</span> avec le plancher pelvi-périnéal</strong>. Les <span class=\"nc-yellow_bg\">efforts expulsifs </span><strong><span class=\"nc-yellow_bg\">volontaires</span></strong><span class=\"nc-yellow_bg\"> doivent être </span><strong><span class=\"nc-yellow_bg\">concomitants des CU</span></strong> pour assurer une bonne descente du mobile fœtal.\n      </div>\n\n      <h4>Technique en inspiration bloquée (Valsalva)</h4>\n\n      <ol>\n        <li><strong><span class=\"nc-blue_bg\">Inspirer</span></strong> → <span class=\"nc-blue_bg\">souffler</span> → <span class=\"nc-blue_bg\">inspirer</span></li>\n        <li><strong><span class=\"nc-blue_bg\">Bloquer la respiration</span></strong></li>\n        <li><strong><span class=\"nc-blue_bg\">Pousser vers le bas</span></strong><span class=\"nc-blue_bg\"> pendant toute la durée de la CU</span></li>\n        <li>Patiente <strong>se repose</strong> entre chaque CU (respiration ample et profonde)</li>\n        <li>Patiente <strong>arrête de pousser</strong> lorsque l’opérateur intervient (respiration lente et profonde) — <span>éviter une expulsion brusque qui risquerait d’entraîner des déchirures</span></li>\n      </ol>\n\n      <p><em>Technique de la <strong>poussée en expiration</strong> également possible (alternative à Valsalva).</em></p>\n\n      <h4>Dégagement du reste du corps</h4>\n\n      <table>\n        <thead>\n          <tr><th>Temps</th><th>Manœuvre</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1. Sortie de la tête — vérification du cordon</strong></td>\n            <td>\n              Vérifier l’<strong>absence de circulaire du cordon</strong> (anomalie : enroulement autour du cou).\n              <ul>\n                <li><strong>Circulaire lâche :</strong> faire glisser autour du thorax fœtal</li>\n                <li><strong>Circulaire serré :</strong> <span>couper entre 2 pinces Kocher</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>2. Rotation de restitution</strong></td>\n            <td>L’opérateur accentue la rotation spontanée — amène l’occiput fœtal à proximité de l’anus maternel (<span class=\"nc-blue_bg\">en OS</span>) → permet aux épaules de passer du <span>diamètre</span> oblique du DS au diamètre antéro-postérieur du DI</td>\n          </tr>\n          <tr>\n            <td><strong>3. Dégagement des épaules</strong></td>\n            <td>\n              Traction douce vers le bas dans l’axe ombilico-coccygien :\n              <ul>\n                <li>Épaule <strong><span class=\"nc-blue_bg nc-bold\">antérieure</span></strong> <span class=\"nc-blue_bg\">puis</span> <strong><span class=\"nc-blue_bg nc-bold\">postérieure</span></strong></li>\n                <li><span class=\"nc-blue nc-bold\">Passage du </span><strong><span><span class=\"nc-blue nc-bold\">diamètre</span></span><span class=\"nc-blue nc-bold\"> bi-acromial</span></strong></li>\n                <li><span>Temps d’extraction des épaules ne doit pas dépasser &lt; 40 secondes</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>4. Expulsion du siège</strong></td>\n            <td>Suit sans difficulté (<span>diamètre</span> bitrochantérien = <span>9 cm</span> seulement)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Après expulsion — clampage du cordon</h4>\n\n      <ul>\n        <li>Enfant posé <strong>sur le ventre de sa mère</strong>, tête en position déclive</li>\n        <li><strong>Clampage précoce</strong> — dès les premières secondes</li>\n        <li><span><strong>Clampage retardé (recommandé)</strong></span> — pendant <strong>&gt; 30 secondes jusqu’à <span <span=\"\">&gt;3</span> minutes</strong> avant le coupage → permet au bébé de bénéficier du transfert du sang du placenta (nutriments + cellules souches)</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : obj-10 (mécanismes périnéaux) · obj-7 (<span>surveillance</span>)</em></p></div>"},{"i":"726b5db71f71","n":31,"o":"31-13","u":"Physiopathologie","t":"Connaître les différents temps de la délivrance","q":"Que retenir concernant les différents temps de la délivrance ?","a":"<div class=\"notion-course\"><p>La <span><span class=\"nc-yellow_bg\">délivrance</span></span> = ensemble des phénomènes physiologiques aboutissant à l’expulsion du placenta et des membranes. Elle <strong>termine l’accouchement</strong> et se déroule en <strong>3 temps</strong>.</p>\n\n      <h4>3 temps de la délivrance</h4>\n\n      <table>\n        <thead>\n          <tr><th>Temps</th><th>Mécanisme</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1. Décollement placentaire</strong></td>\n            <td>\n              <ol>\n                <li><strong><span class=\"nc-yellow_bg\">Rétraction utérine</span></strong> dès la sortie de l’enfant → <span>réduction</span> de la surface d’insertion placentaire (villosités crampons tirent sur la muqueuse, amorçant le clivage et déchirant les sinus veineux)</li>\n                <li><strong>Intensification des CU</strong> après expulsion du fœtus → clivage (= cause essentielle ; fond utérin remonte au-dessus de l’ombilic)</li>\n                <li><strong>Hématome rétro-placentaire physiologique</strong> → complète la séparation</li>\n              </ol>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>2. Expulsion du placenta</strong></td>\n            <td>\n              Mécanisme principal : <strong>contractions utérines</strong>. Plus accessoirement : efforts expulsifs, poids du placenta, hématome inter-utéro-placentaire.<br>\n              <strong>Manœuvre douce :</strong>\n              <ul>\n                <li>1 main <span class=\"nc-blue_bg\">empaume le fond utérin pour abaisser le placenta fermement vers le bas</span></li>\n                <li>1 main maintient le cordon <strong>tendu <span class=\"nc-blue_bg nc-bold\">sans traction</span></strong></li>\n              </ul>\n              <span>⚠️ Ne pas tirer sur le cordon, ne pas exécuter de manœuvres hâtives</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>3. Hémostase</strong></td>\n            <td>\n              Assurée par :\n              <ul>\n                <li><strong><span class=\"nc-yellow_bg\">Thrombose des vaisseaux</span></strong> (facteurs de la coagulation)</li>\n                <li><strong><span class=\"nc-yellow_bg\">Rétraction utérine</span></strong> = phénomène des <span>ligatures vivantes</span> (<span class=\"nc-yellow_bg\">faisceaux musculaires de la couche plexiforme enserrent et obturent les vaisseaux</span>)</li>\n              </ul>\n              <em>Mécanisme efficace uniquement après évacuation totale de la cavité utérine.</em>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Reconnaissance clinique du décollement placentaire</h4>\n\n      <ul>\n        <li><strong><span class=\"nc-blue_bg\">Métrorragie</span></strong></li>\n        <li><strong><span class=\"nc-blue_bg\">Déroulement du cordon</span></strong><span class=\"nc-blue_bg\"> hors de la vulve</span> (pince témoin objective la descente)</li>\n        <li>Pression sus-pubienne / mobilisation utérine vers le haut <strong><span class=\"nc-yellow_bg\">ne fait pas remonter le cordon</span></strong> = <span>signe d’affirmation du décollement</span></li>\n        <li>Redescente du fond utérin après ascension momentanée</li>\n        <li><span>TV</span> susceptible d’affirmer la présence du placenta dans le vagin</li>\n      </ul>\n\n      <h4>Examen du placenta</h4>\n\n      <ul>\n        <li>Présentation à l’orifice vulvaire :\n          <ul>\n            <li><strong>Face fœtale</strong> — le plus souvent (mode <span><span class=\"nc-blue nc-bold\">Baudelocque</span></span>)</li>\n            <li><strong>Face maternelle ou bord</strong> — parfois (mode Duncan)</li>\n          </ul>\n        </li>\n        <li><strong>Sac membraneux :</strong> inspecté par transparence à la recherche d’une <span>zone dépolie/granuleuse où arrivent des vaisseaux</span> = <strong><span class=\"nc-red nc-bold\">cotylédon aberrant</span></strong> (<span class=\"nc-red nc-bold\">insertion sur les membranes à distance de la </span><span><span class=\"nc-red nc-bold\">masse</span></span><span class=\"nc-red nc-bold\"> placentaire</span>)</li>\n        <li><strong>Face fœtale :</strong> noter le lieu d’insertion du cordon, contrôler la présence de <span><span class=\"nc-pink nc-bold\">2 artères</span> + <span class=\"nc-pink nc-bold\">1 veine</span></span><span class=\"nc-pink nc-bold\"> funiculaires</span></li>\n        <li><strong>Face maternelle :</strong> débarrassée des caillots, cotylédons doivent se juxtaposer sans solution de continuité</li>\n      </ul>\n\n      <h4>Délivrance dirigée</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Délivrance dirigée — prévention HPP.</strong>\n        <ul>\n          <li><strong>Objectif :</strong> <span class=\"nc-green nc-bold\">prévention de l’hémorragie de la délivrance</span></li>\n          <li><strong>Principe :</strong> administration préventive d’<span>oxytocine IV 5–10 UI</span> (utérotonique)</li>\n          <li><strong>Quand ?</strong> idéalement <strong>au moment du dégagement des épaules</strong>, ou <span class=\"nc-pink nc-bold\">rapidement après la naissance</span></li>\n        </ul>\n      </div>\n\n      <h4><span>Délivrance artificielle</span> &amp; révision utérine</h4>\n\n      <table>\n        <thead>\n          <tr><th>Geste</th><th>Indication</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Délivrance artificielle</span></strong></td>\n            <td>Patiente <span>non délivrée après 30 minutes</span></td>\n          </tr>\n          <tr>\n            <td><strong><span>Révision utérine</span></strong></td>\n            <td>\n              <ul>\n                <li>Placenta incomplet (cotylédon manquant, absence du sac membraneux)</li>\n                <li><span><span class=\"nc-orange_bg\">Hémorragie du post-partum immédiat</span></span> (volume de sang perdu <span>≥ 500 cm³</span>)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Après l’hémostase — globe de sécurité.</strong>\n        <ul>\n          <li>Femme <strong><span class=\"nc-green nc-bold\">soulagée</span>, <span class=\"nc-green nc-bold\">détendue</span>, FC/PA normales</strong></li>\n          <li><span class=\"nc-yellow_bg\">Utérus</span> <span class=\"nc-yellow_bg nc-bold\">diminue de taille</span> → <span>masse</span> <strong><span class=\"nc-yellow_bg nc-bold\">dure</span> et <span class=\"nc-yellow_bg nc-bold\">arrondie</span></strong> en <span class=\"nc-yellow_bg nc-bold\">région sus-pubienne</span> = <span><span class=\"nc-yellow_bg\">globe de sécurité</span></span></li>\n        </ul>\n        Absence de globe de sécurité = <span>atonie utérine</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 24 — Complications de la <span>grossesse</span> · 34 — Suites de couches pathologiques · 332 — États de <span>choc</span> (HPP)</em></p></div>"},{"i":"a0bf5b9f5f16","n":31,"o":"31-14","u":"Physiopathologie","t":"Connaître les suites de couche normales","q":"Que retenir concernant les suites de couche normales ?","a":"<div class=\"notion-course\"><p>Les <span>suites de couches</span> = période d’<strong>environ <span><span class=\"nc-pink_bg\">6 semaines</span></span> (<span><span class=\"nc-pink_bg\">40 jours</span></span>)</strong> qui débute <strong><span><span class=\"nc-pink nc-bold\">2 h</span></span><span class=\"nc-pink nc-bold\"> après</span> l’accouchement</strong> et se termine par le <strong><span class=\"nc-green_bg\">retour de couches</span></strong><span class=\"nc-green_bg\"> (retour des menstruations)</span>.</p>\n\n      <h4>Éléments cliniques de <span>surveillance</span></h4>\n\n      <ul>\n        <li><strong>Signes généraux</strong> — pouls, PA, température, état général, douleur</li>\n        <li><strong>Seins</strong> — tension, douleur, crevasses</li>\n        <li><strong>Involution du globe utérin</strong> — hauteur et <span class=\"nc-blue nc-bold\">consistance</span> de l’<span class=\"nc-yellow_bg\">utérus</span></li>\n        <li><strong>Cicatrisation périnéale</strong></li>\n        <li><strong>Lochies</strong> (écoulement vaginal sanglant du post-partum) — abondance, aspect, odeur</li>\n        <li><strong>Membres inférieurs</strong> — recherche de signes de phlébite</li>\n        <li><strong>Appareil urinaire</strong> — signes fonctionnels, aspect des urines</li>\n        <li><strong>Si césarienne</strong> — cicatrice, douleur, reprise du transit, mictions et couleur des urines</li>\n      </ul>\n\n      <p><span>Hospitalisation</span> possible jusqu’au <span>12<sup>e</sup> jour</span> pour la sécurité sociale.</p>\n\n      <h4>Involution utérine</h4>\n\n      <table>\n        <thead>\n          <tr><th>Élément</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Mécanisme</strong></td>\n            <td><span class=\"nc-yellow_bg\">Diminution du volume</span> + <span class=\"nc-yellow_bg\">réintégration de l’utérus dans la cavité pelvienne</span> (sous l’influence de <strong>CU infracliniques</strong>, <span><span class=\"nc-blue nc-bold\">douloureuses chez la multipare</span></span> = « <span>tranchées</span> »)</td>\n          </tr>\n          <tr>\n            <td><strong>Facteurs favorisants</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-brown_bg\">Prescription d’</span><span><span class=\"nc-brown_bg\">ocytociques</span></span> (favorisent les CU et donc l’involution)</li>\n                <li><span>Allaitement</span> maternel (la succion du nouveau-né stimule la libération d’ocytocine)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>Évolution</span></strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-yellow_bg\">Utérus</span> gros/globuleux pendant <span>15 jours</span> → retrouve sa taille normale en <span>2–3 mois</span></li>\n                <li>Reconstitution du col utérin :\n                  <ul>\n                    <li>Col prend de la longueur et de la consistance</li>\n                    <li>Fermeture de l’orifice interne : vers le <span><span class=\"nc-pink nc-bold\">10</span><sup><span class=\"nc-pink nc-bold\">e</span></sup><span class=\"nc-pink nc-bold\"> jour</span></span></li>\n                    <li>Fermeture de l’orifice externe : vers le <span><span class=\"nc-pink nc-bold\">15–20</span><sup><span class=\"nc-pink nc-bold\">e</span></sup><span class=\"nc-pink nc-bold\"> jour</span></span></li>\n                    <li>Disparition du segment inférieur : <span class=\"nc-pink nc-bold\">en quelques jours</span></li>\n                  </ul>\n                </li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Lochies</h4>\n\n      <ul>\n        <li><strong><span class=\"nc-pink nc-bold\">4 premiers jours</span> :</strong> écoulement sérosanguinolent/sanglant physiologique</li>\n        <li><strong><span class=\"nc-green_bg\">Éclaircissement progressif</span> :</strong> lochies <strong>totalement claires vers J10</strong></li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Globe de sécurité.</strong> L’utérus doit conserver le classique <span>globe de sécurité</span> (utérus rétracté et tonique) lors du séjour en maternité.\n        <ul>\n          <li>Contrôle <strong>journalier</strong> de l’involution utérine</li>\n          <li>Pathologies où l’utérus est mal involué : <span><span class=\"nc-orange nc-bold\">atonie utérine</span></span>, <span><span class=\"nc-orange nc-bold\">endométrite du post-partum</span></span></li>\n        </ul>\n      </div>\n\n      <h4>Retour de couches &amp; ovulation</h4>\n\n      <table>\n        <thead>\n          <tr><th>Élément</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Reconstitution endomètre (3 phases)</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-yellow_bg\">Régression</span> : <span>4–5 jours</span> (dégénérescence de la caduque)</li>\n                <li><span class=\"nc-yellow_bg\">Cicatrisation</span> : jusqu’au 25<sup>e</sup> jour</li>\n                <li><span class=\"nc-yellow_bg\">Prolifération</span> : 25–45<sup>e</sup> jour</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Sans <span>allaitement</span></strong></td>\n            <td>Retour de couches vers le <span>45<sup>e</sup> jour</span> post-partum (<span>6–12 semaines</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Avec <span>allaitement</span> maternel</strong></td>\n            <td>Retour en <span>4–6 mois</span> (≈ <span><span class=\"nc-pink_bg\">40 jours</span></span> après la fin de l’<span>allaitement</span>) — endomètre garde un aspect régressif de repos</td>\n          </tr>\n          <tr>\n            <td><strong>Petit retour de couches</strong></td>\n            <td>Hémorragie de faible abondance vers le <strong>20<sup>e</sup> jour</strong> pendant <span>2–3 jours</span></td>\n          </tr>\n          <tr>\n            <td><strong>Ovulation</strong></td>\n            <td>\n              <span>1<sup>er</sup> cycle peut être ovulatoire dans 5–10 % des cas</span><br>\n              <strong>L’<span>allaitement</span> maternel n’est pas une contraception garantie</strong> ⚠️\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Sécrétion lactée</h4>\n\n      <table>\n        <thead>\n          <tr><th>Hormone</th><th>Rôle</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span><span class=\"nc-pink nc-bold\">Prolactine</span></span></strong></td>\n            <td>Conditionne la <strong>synthèse + stockage/sécrétion</strong> du lait par les lactocytes (galactopoïèse)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-pink nc-bold\">Ocytocine</span></strong></td>\n            <td>Favorise l’<strong><span class=\"nc-green_bg\">éjection du lait</span></strong> en stimulant la contraction des cellules myo-épithéliales autour des lactocytes</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Montée laiteuse</strong> — survient au <span>2–3<sup>e</sup> jour</span> du post-partum (= 2<sup>e</sup> phase de la lactogenèse) :\n        <ul>\n          <li>Seins gonflent, tendus et sensibles, <strong><span class=\"nc-blue_bg\">fébricule</span> transitoire possible à <span>38 °C</span></strong></li>\n          <li>Liée à l’asynchronisme entre lactogenèse et mécanismes d’<span class=\"nc-green_bg\">éjection du lait</span></li>\n          <li>Normalisation par tétées fréquentes et efficaces</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : obj-14 (PEC post-partum immédiat) · obj-15 (contraception) · 34 — Suites de couches pathologiques · 69 — Troubles psychiques de la <span>grossesse</span> et du post-partum</em></p></div>"},{"i":"1427872e6dc3","n":31,"o":"31-15","u":"Prise en charge","t":"Savoir prendre en charge une accouchée dans le post-partum immédiat","q":"Que retenir concernant prendre en charge une accouchée dans le post-partum immédiat ?","a":"<div class=\"notion-course\"><p>La prise en charge du <span>post-partum immédiat</span> vise 5 objectifs structurants pendant le séjour en maternité.</p>\n\n      <h4>5 objectifs du séjour en maternité</h4>\n\n      <ul>\n        <li><strong>Favoriser et contrôler</strong> la bonne involution de l’utérus + s’assurer de l’absence d’hémorragie</li>\n        <li><strong>Contrôler l’<span>allaitement</span></strong></li>\n        <li><strong>Prévenir et dépister</strong> les infections locales et générales + les accidents thromboemboliques</li>\n        <li><strong>Soins du périnée</strong> — toilettes fréquentes, éviter la macération, information sur la rééducation pelvi-périnéale</li>\n        <li><strong>Information médicale + actions de prévention</strong></li>\n      </ul>\n\n      <h4><span>Allaitement</span> maternel — bonnes pratiques</h4>\n\n      <table>\n        <thead>\n          <tr><th>Item</th><th>Recommandation</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1<sup>re</sup> tétée</strong></td>\n            <td><span class=\"nc-green_bg\">Mise au sein </span><strong><span class=\"nc-green_bg\">immédiate</span></strong>, <span class=\"nc-green_bg\">si possible en salle de travail</span> (sans précipitation, <span><span class=\"nc-pink nc-bold\">&lt; 30 min</span></span> après la naissance) — le colostrum est très riche en Ig, et le réflexe de succion est à son maximum</td>\n          </tr>\n          <tr>\n            <td><strong>Installation</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-blue_bg\">Mère assise ou couchée</span>, <span class=\"nc-blue_bg\">donner les </span><strong><span class=\"nc-blue_bg\">2 seins à chaque tétée</span></strong> (alterner = diminue les complications)</li>\n                <li><span class=\"nc-yellow_bg\">Bouche du nouveau-né doit prendre </span><strong><span class=\"nc-yellow_bg\">largement l’aréole</span></strong> (<span class=\"nc-red nc-bold\">pas seulement le mamelon</span>)</li>\n                <li><span class=\"nc-blue nc-bold\">Menton</span> et <span class=\"nc-blue nc-bold\">nez</span> contre le sein, tête légèrement inclinée en arrière</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Horaires</strong></td>\n            <td>\n              <span>Allaitement</span> <strong>souple à la demande</strong>. Fréquence moyenne : <span>1 tétée toutes les 2–3 h au début</span>, puis espacement progressif guidé par le nouveau-né.\n              <ul>\n                <li>Signes : regard/comportement (mouvements <span class=\"nc-blue nc-bold\">yeux</span>, lèvres, tête, main à la <span class=\"nc-blue nc-bold\">bouche</span>)</li>\n                <li><span class=\"nc-red_bg\">Ne pas attendre l’agitation ou les pleurs</span></li>\n                <li><span class=\"nc-red_bg\">Ne pas juger seulement sur la courbe de poids</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Durée</strong></td>\n            <td>Variable selon l’enfant — très courte (efficace, actif) à plus longue (prématurés, lent, tétouille)</td>\n          </tr>\n          <tr>\n            <td><strong>Signes d’<span>allaitement</span> efficace</strong></td>\n            <td>\n              <ul>\n                <li><strong>Tétées</strong> —<span> 8–12<span class=\"nc-yellow_bg\">/jour</span></span> de façon efficace (<span class=\"nc-green_bg\">y compris la nuit pendant les 1</span><sup><span class=\"nc-green_bg\">ers</span></sup><span class=\"nc-green_bg\"> mois</span>)</li>\n                <li><strong>Selles</strong> — &gt;<span> 3<span class=\"nc-yellow_bg\">/jour</span></span> <span class=\"nc-yellow_bg nc-bold\">molles</span>, <span class=\"nc-yellow_bg nc-bold\">grumeleuses</span>, <span class=\"nc-yellow_bg nc-bold\">jaunes</span></li>\n                <li><strong>Urines</strong> — <span class=\"nc-yellow_bg\">5–6 couches mouillées et lourdes/jour</span> (diurèse satisfaisante)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Conseils à favoriser ✅</h4>\n\n      <ul>\n        <li>Laisser l’enfant avec sa mère <strong><span>24 h</span> sur 24</strong></li>\n        <li><span class=\"nc-blue_bg\">Lavage quotidien des seins à l’eau et au savon</span></li>\n        <li>Protection des mamelons avec compresse sèche (éviter macération)</li>\n        <li>Encourager les associations de soutien à l’<span>allaitement</span> maternel</li>\n        <li>Boissons abondantes, alimentation variée et riche en protéines et calcium</li>\n      </ul>\n\n      <h4>À éviter ❌</h4>\n\n      <ul>\n        <li><strong>Proscription du <span>tabac</span>, <span>alcool</span>, excitants</strong> (café, thé)</li>\n        <li><strong>Pas de tétine artificielle ou sucette</strong> chez l’enfant allaité</li>\n        <li>Éviter les crèmes cosmétiques sur les seins ; <strong>pas d’antisepsie nécessaire</strong></li>\n        <li>Aucun médicament ou régime alimentaire censé augmenter la sécrétion lactée</li>\n        <li>Production de lait diminue si ajout de biberons (moins de stimulation)</li>\n      </ul>\n\n      <h4>Prévention de la maladie thromboembolique veineuse (MTEV)</h4>\n\n      <table>\n        <thead>\n          <tr><th>Niveau de risque</th><th>Facteurs</th><th>Prophylaxie</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Risque majeur</strong></td>\n            <td>\n              <ul>\n                <li>ATCD de <strong><span class=\"nc-red nc-bold\">MTEV multiples</span></strong></li>\n                <li><strong><span class=\"nc-red nc-bold\">Thrombophilie</span></strong><span class=\"nc-red nc-bold\"> traitée au long cours</span> par <span>anticoagulant</span></li>\n              </ul>\n            </td>\n            <td><span class=\"nc-green_bg\">Bas de contention</span> + <strong><span><span class=\"nc-pink nc-bold\">AVK</span></span></strong> pendant <span><span class=\"nc-pink nc-bold\">≥ 3 mois</span></span></td>\n          </tr>\n          <tr>\n            <td><strong>Risque élevé</strong></td>\n            <td>\n              <ul>\n                <li>ATCD MTEV sans FR retrouvé</li>\n                <li>ATCD MTEV en contexte de <span>grossesse</span> ou de traitement œstrogénique</li>\n                <li>ATCD MTEV + facteur <span>biologique</span> (déficit AT, <span class=\"nc-red\">SAPL</span>, mutation <span class=\"nc-red\">20210A</span> homozygote, <span>FV <span class=\"nc-red\">Leiden</span></span> homozygote, anomalies hétérozygotes combinées)</li>\n              </ul>\n            </td>\n            <td><span class=\"nc-green_bg\">Bas de contention</span> + <strong><span><span class=\"nc-pink nc-bold\">HBPM à dose prophylactique forte</span></span></strong> (<span>énoxaparine</span> 4 <span>000 UI</span>/j ou <span>daltéparine</span> 5 <span>000 UI</span>/j) pendant <span>6–8 semaines</span></td>\n          </tr>\n          <tr>\n            <td><strong>Risque modéré</strong></td>\n            <td>\n              <ul>\n                <li>ATCD MTEV avec facteur déclenchant temporaire</li>\n                <li>ATCD MTEV + autre facteur <span>biologique</span></li>\n                <li>Facteur <span>biologique</span> asymptomatique dépisté dans une MTEV familiale</li>\n                <li><strong><span class=\"nc-pink_bg\">Césarienne en </span><span><span class=\"nc-pink_bg\">urgence</span></span></strong></li>\n                <li>Césarienne + <span>chirurgie</span> pelvienne majeure associée</li>\n                <li>Présence de <span>≥ 3</span> FR faibles</li>\n              </ul>\n            </td>\n            <td><span class=\"nc-green_bg\">Bas de contention</span> + <strong><span><span class=\"nc-pink nc-bold\">HBPM à dose prophylactique forte</span></span></strong> pendant <span>6–8 semaines</span> (dose et durée modulables)</td>\n          </tr>\n          <tr>\n            <td><strong>Risque faible</strong></td>\n            <td>\n              Si &lt; 3 FR suivants : <span class=\"nc-pink_bg\">âge &gt;</span><span><span class=\"nc-pink_bg\"> 35 ans</span></span>, <span><span class=\"nc-pink_bg\">obésité</span></span> (IMC &gt; 30 ou poids &gt;<span> 80 kg</span>), <span class=\"nc-pink_bg\">varices</span>, <span><span class=\"nc-pink_bg\">HTA</span></span>, <span class=\"nc-blue_bg\">césarienne</span>, <span class=\"nc-blue_bg\">multiparité &gt; 4</span>, <span><span class=\"nc-blue_bg\">prééclampsie</span></span>, <span class=\"nc-blue_bg\">alitement strict prolongé</span>, HPP, <span>syndrome néphrotique</span>, <span>MICI</span> en poussée, infection systémique\n            </td>\n            <td><span class=\"nc-green_bg\">Bas de contention</span> seuls — <span>pas d’anticoagulant</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : obj-13 (suites de couches) · obj-15 (contraception PP) · 34 — Suites de couches pathologiques · 226 — <span>TVP</span> / EP · 69 — Troubles psychiques de la <span>grossesse</span> et du PP</em></p></div>"},{"i":"e18f57edc665","n":31,"o":"31-16","u":"Prise en charge","t":"Savoir prescrire une contraception du post partum","q":"Que retenir concernant prescrire une contraception du post partum ?","a":"<div class=\"notion-course\"><p>La <span>contraception du post-partum</span> est <strong>provisoire</strong> et devra être rediscutée à la visite postnatale. Sa précocité de mise en place est cruciale : la reprise de la fertilité est précoce (mais pas avant <span>25 jours</span>).</p>\n\n      <h4>Généralités</h4>\n\n      <table>\n        <thead>\n          <tr><th>Élément</th><th>Donnée clé</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Reprise des rapports</strong></td>\n            <td>En moyenne <span>5 semaines</span> après l’accouchement — à <span>1 mois</span>, ≈ <span>60 %</span> des couples ont eu <span>≥ 1</span> rapport</td>\n          </tr>\n          <tr>\n            <td><strong>IVG post-PP</strong></td>\n            <td><span>5,5 % des IVG en France</span> surviennent dans les <span>6 mois</span> après un accouchement (≈ 11 000 femmes/an)</td>\n          </tr>\n          <tr>\n            <td><strong>Reprise de la fertilité</strong></td>\n            <td>Précoce, mais <strong>pas avant <span>25 jours</span></strong> → <span>débuter la contraception vers le 21<sup>e</sup> jour</span></td>\n          </tr>\n          <tr>\n            <td><strong>Visite postnatale</strong></td>\n            <td><span>30 %</span> des femmes n’ont pas repris ou ont abandonné leur contraception → méthode prescrite souvent non adaptée à toutes</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Quand reprendre l’activité sexuelle ?</h4>\n\n      <p>Dès que le <strong>périnée est confortable et guéri</strong> et que le <strong>sang rouge clair a disparu</strong> : <span><span class=\"nc-pink nc-bold\">2–3 semaines</span></span>.</p>\n\n      <h4>Méthodes contraceptives — post-partum</h4>\n\n      <table>\n        <thead>\n          <tr><th>Méthode</th><th>Modalités en post-partum</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Méthodes barrières</strong> ✅</td>\n            <td>\n              <span class=\"nc-blue_bg\">Préservatifs</span>, <span class=\"nc-blue_bg\">spermicides (crèmes, ovules, éponges)</span>.<br>\n              <span><span class=\"nc-red nc-bold\">Diaphragme plus difficile à utiliser en post-partum</span> ❌</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>DIU (stérilet)</strong></td>\n            <td>\n              <strong>Avantages :</strong>\n              <ul>\n                <li><span class=\"nc-green_bg\">Pose sans danger</span> (risque infection/perforation non augmenté)</li>\n                <li>Méthode idéale chez la femme qui allaite (aucun effet sur la qualité/composition du lait)</li>\n              </ul>\n              <strong>Inconvénient principal :</strong>\n              <ul>\n                <li><span><span class=\"nc-red nc-bold\">Taux élevé d’expulsion</span></span> à cause des CU et de la dilatation cervicale (<span>12–40 %</span> expulsés à <span>6 mois</span>)</li>\n                <li><strong>Prévention :</strong> <span class=\"nc-pink nc-bold\">pose idéalement après </span><span><span class=\"nc-pink nc-bold\">≥ 3 mois</span></span> (après retour de couches ou en fin d’involution utérine)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Œstro-progestatifs (COP)</strong> ❌</td>\n            <td>\n              <strong>Ne pas prescrire avant le 3<sup>e</sup> mois</strong> après un accouchement :\n              <ul>\n                <li><span><span class=\"nc-red nc-bold\">Risque thrombotique majoré</span></span> (pendant <span>grossesse</span> + post-partum pendant <span>≥ 6–9 semaines</span>)</li>\n                <li><span><span class=\"nc-red nc-bold\">Risque d’ablactation</span></span><span class=\"nc-red nc-bold\"> avant </span><span><span class=\"nc-red nc-bold\">6 semaines</span></span> chez la femme allaitante</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Micro-progestatifs</strong> ✅</td>\n            <td>\n              <ul>\n                <li><strong>Quand ?</strong> en continu <strong><span class=\"nc-green_bg nc-bold\">à partir du 21</span><sup><span class=\"nc-green_bg nc-bold\">e</span></sup><span class=\"nc-green_bg nc-bold\"> jour</span></strong> (voie orale ou implant)</li>\n                <li><strong>Inconvénients :</strong> <span class=\"nc-red nc-bold\">métrorragies</span>, <span class=\"nc-red nc-bold\">spottings</span> (taches de sang en dehors des règles)</li>\n                <li><strong>Avantages :</strong> pas de répercussions métaboliques/systémiques, effet sur l’<span>allaitement</span> et l’enfant négligeable</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Stérilisation</strong></td>\n            <td>\n              <ul>\n                <li><strong>Quand ?</strong> au moment d’une césarienne, ou dans les <span>24–48 h</span> après un accouchement non compliqué</li>\n                <li><strong>Vigilance :</strong> <span>stérilisation s’accompagne plus souvent de regrets en post-partum immédiat</span></li>\n                <li><strong>Avantage :</strong> n’allonge pas l’<span>hospitalisation</span>. Taux d’échec <span>0,5–1 %</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Méthode MAMA (<span>allaitement</span> maternel et aménorrhée)</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>MAMA — méthode naturelle pendant les 6 premiers mois</strong>\n        <ul>\n          <li><strong>Principe :</strong> <span><span class=\"nc-blue nc-bold\">allaitement</span></span><span class=\"nc-blue nc-bold\"> </span><strong><span class=\"nc-blue nc-bold\">exclusif à la demande</span></strong>, <span class=\"nc-blue nc-bold\">jour et nuit</span> + persistance d’une aménorrhée</li>\n          <li><strong>Efficacité :</strong> indice de Pearl à <span>7 %</span> (taux <span>grossesse</span> à<span> 1 an</span>)</li>\n          <li><strong>Conseil :</strong> <span class=\"nc-pink_bg\">associer une contraception locale (</span><span class=\"nc-pink_bg nc-bold\">préservatifs</span>, <span class=\"nc-pink_bg nc-bold\">spermicides</span><span class=\"nc-pink_bg\">) pour potentialiser l’efficacité</span></li>\n          <li><strong>Précaution :</strong> <span>allaitement doit être exclusif</span>, sinon une méthode fiable est nécessaire</li>\n        </ul>\n      </div>\n\n      <h4>Contraception et <span>allaitement</span> — résumé</h4>\n\n      <table>\n        <thead>\n          <tr><th>Méthode</th><th>Compatibilité avec l’allaitement</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Œstro-progestatifs</strong></td><td><span>❌ Pas recommandés</span> — risque thromboembolique + diminution de la production lactée</td></tr>\n          <tr><td><strong>Micro-progestatifs, <span class=\"nc-green_bg\">implants progestatifs</span></strong></td><td>✅ Utilisables sans inconvénient</td></tr>\n          <tr><td><strong>DIU</strong></td><td>✅ Sans danger</td></tr>\n          <tr><td><strong><span class=\"nc-blue_bg\">Préservatifs</span>, <span class=\"nc-blue_bg\">spermicides</span></strong></td><td>✅ Utilisables (efficacité limitée, contraignants)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Risque d’ovulation au cours de l’<span>allaitement</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Situation</th><th>6 sem.</th><th>9 sem.</th><th>12 sem.</th><th>18 sem.</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span>Allaitement</span> en cours</strong></td><td><span>0 %</span></td><td><span>1 %</span></td><td><span>17 %</span></td><td><span>36 %</span></td></tr>\n          <tr><td><strong><span>Allaitement</span> &lt; <span>6 semaines</span></strong></td><td><span>12 %</span></td><td><span>79 %</span></td><td><span>99 %</span></td><td>—</td></tr>\n          <tr><td><strong><span>Allaitement</span> &lt; <span>4 semaines</span></strong></td><td><span>14 %</span></td><td><span>89 %</span></td><td><span>99,5 %</span></td><td>—</td></tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 36 — Contraception · obj-13 (suites de couches) · obj-14 (PEC post-partum) · 34 — Suites de couches pathologiques</em></p></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d94181ba9f87c0bf125017a5?pvs=204","reviewedAt":"2026-10-15","note":"Cours personnel, couleurs des passages Notion correspondants, corrections et parcours interactifs sourcés. Les compléments sont distingués des figures d’origine."},"liensGlobaux":[{"href":"https://cego-obgyn.fr/deuxieme-cycle/","label":"Collège CNGOF–CEGO · Référentiel, 6e édition 2024"},{"href":"https://cngof.fr/app/uploads/2025/11/Accouchement202017-RPC_HAS-CNGOF_Recommandations.pdf","label":"HAS–CNGOF · Accouchement normal, 2017"}]};
